ally(newPassword);\r\n    setPasswordStrength(result.message);\r\n    setStrengthScore(result.score);\r\n  };\r\n\r\n  const handleSubmit = async (e) => {\r\n    e.preventDefault();\r\n    const newErrors = {};\r\n    if (!email.trim()) newErrors.email = 'Email is required';\r\n    else if (!/\\S+@\\S+\\.\\S+/.test(email)) newErrors.email = 'Email address is invalid';\r\n    if (!password) newErrors.password = 'Password is required';\r\n    else if (password.length < 6) newErrors.password = 'Password must be at least 6 characters long';\r\n    setErrors(newErrors);\r\n    if (Object.keys(newErrors).length > 0) return;\r\n    setLoading(true);\r\n    try {\r\n      const response = await auth.login(email, password);\r\n      if (response.success) {\r\n        toast({\r\n          title: 'Login Successful!',\r\n          description: 'Redirecting to home page.',\r\n          status: 'success',\r\n          duration: 5000,\r\n          isClosable: true,\r\n        });\r\n        navigate('/home');\r\n      } else {\r\n        toast({\r\n          title: 'Login Error',\r\n          description: response.message || 'Invalid credentials',\r\n          status: 'error',\r\n          duration: 5000,\r\n          isClosable: true,\r\n        });\r\n      }\r\n    } catch (error) {\r\n      let errorMessage = error.message || 'Login failed';\r\n      if (error.response?.status === 400) errorMessage = 'Invalid request format. Please try again.';\r\n      toast({\r\n        title: 'Login Error',\r\n        description: errorMessage,\r\n        status: 'error',\r\n        duration: 5000,\r\n        isClosable: true,\r\n      });\r\n    } finally {\r\n      setLoading(false);\r\n    }\r\n  };\r\n\r\n  const handleGoogleLogin = () => {\r\n    const backendUrl = process.env.REACT_APP_BACKEND_URL || 'http://localhost:5000';\r\n    window.location.href = `${backendUrl}/api/auth/google?action=login`;\r\n  };\r\n\r\n  return (\r\n    <Flex\r\n      minH=\"100vh\"\r\n      align=\"center\"\r\n      justify=\"center\"\r\n      p={4}\r\n      position=\"relative\"\r\n      backgroundImage={`url(${gridXBackground})`}\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n    >\r\n      <Box\r\n        position=\"absolute\"\r\n        top=\"0\"\r\n        left=\"0\"\r\n        right=\"0\"\r\n        bottom=\"0\"\r\n        bg=\"rgba(0, 0, 0, 0.5)\"\r\n        zIndex=\"1\"\r\n      />\r\n      <Box\r\n        maxW=\"md\"\r\n        w=\"full\"\r\n        bg={useColorModeValue('rgba(255, 255, 255, 0.8)', 'rgba(0, 0, 0, 0.6)')}\r\n        boxShadow=\"xl\"\r\n        borderRadius=\"xl\"\r\n        p={8}\r\n        position=\"relative\"\r\n        zIndex=\"2\"\r\n        backdropFilter=\"blur(16px)\"\r\n        border=\"1px solid\"\r\n        borderColor={useColorModeValue('gray.200', 'gray.600')}\r\n      >\r\n        <Heading as=\"h2\" size=\"xl\" mb={6} color={useColorModeValue('gray.800', 'white')} textAlign=\"center\">\r\n          Log In\r\n        </Heading>\r\n        <VStack as=\"form\" spacing={4} onSubmit={handleSubmit} noValidate>\r\n          <FormControl id=\"email\" isInvalid={!!errors.email}>\r\n            <FormLabel>Email</FormLabel>\r\n            <Input type=\"email\" value={email} onChange={(e) => setEmail(e.target.value)} placeholder=\"Enter email\" />\r\n            <FormErrorMessage>{errors.email}</FormErrorMessage>\r\n          </FormControl>\r\n          <FormControl id=\"password\" isInvalid={!!errors.password}>\r\n            <FormLabel>Password</FormLabel>\r\n            <Input type=\"password\" value={password} onChange={handlePasswordChange} placeholder=\"Enter password\" />\r\n            {passwordStrength && <Text mt={2} color=\"gray.600\" fontSize=\"sm\">{passwordStrength}</Text>}\r\n            <Progress value={strengthScore} size=\"xs\" mt={2} colorScheme={strengthScore > 60 ? 'green' : strengthScore > 20 ? 'yellow' : 'red'} />\r\n            <FormErrorMessage>{errors.password}</FormErrorMessage>\r\n          </FormControl>\r\n          <Button type=\"submit\" colorScheme=\"blue\" width=\"full\" isLoading={loading}>Log In</Button>\r\n          <Button width=\"full\" onClick={handleGoogleLogin} leftIcon={<FcGoogle />} variant=\"outline\">Sign in with Google</Button>\r\n          <Text color={useColorModeValue('gray.800', 'white')} mt={4} textAlign=\"center\">\r\n            Don't have an account?{' '}\r\n            <Button variant=\"link\" color=\"blue.500\" onClick={() => navigate('/register')}>Register</Button>\r\n          </Text>\r\n        </VStack>\r\n      </Box>\r\n    </Flex>\r\n  );\r\n}\r\n\r\nexport default LoginPage;","/* eslint-disable no-unused-vars */\r\nimport React from 'react';\r\nimport { useNavigate, Link as RouterLink } from 'react-router-dom';\r\nimport {\r\n  Box,\r\n  Container,\r\n  Heading,\r\n  Text,\r\n  VStack,\r\n  HStack,\r\n  Avatar,\r\n  useColorModeValue,\r\n  Button,\r\n  Flex,\r\n  SimpleGrid,\r\n  Link,\r\n} from '@chakra-ui/react';\r\nimport { FaArrowLeft, FaTwitter, FaFacebook, FaInstagram, FaEnvelope } from 'react-icons/fa';\r\nimport kgImg from '../assets/images/kg_img.png';         // Kgotatso Mokgashi\r\nimport mphoImg from '../assets/images/Mpho.png';         // Mpho Ramokhoase\r\nimport liheImg from '../assets/images/Lihle.png';        // Thembelihle Zulu\r\nimport nathiImg from '../assets/images/IMG Nathii.jpg';  // Nkosinathi Radebe\r\nimport okuhleImg from '../assets/images/sleigh.png';     // Okuhle Gadla\r\nimport aboutBg from '../assets/images/About_Page_IMG.png';\r\n\r\nfunction AboutPage() {\r\n  const navigate = useNavigate();\r\n  const bgColor = useColorModeValue('gray.50', 'gray.900');\r\n  const cardBg = useColorModeValue('white', 'gray.800');\r\n  const textColor = useColorModeValue('gray.700', 'gray.200');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const borderColor = useColorModeValue('gray.200', 'gray.700');\r\n\r\n  // Call useColorModeValue for the developer card background outside the loop\r\n  const developerCardBg = useColorModeValue('gray.100', 'gray.700');\r\n\r\n  // Developer data\r\n  const team = [\r\n    {\r\n      name: \"Kgotatso Mokgashi\",\r\n      role: \"Backend\",\r\n      avatar: kgImg,\r\n      initials: \"KM\"\r\n    },\r\n    {\r\n      name: \"Okuhle Gadla\",\r\n      role: \"Backend\",\r\n      avatar: okuhleImg,\r\n      initials: \"OG\"\r\n    },\r\n    {\r\n      name: \"Thembelihle Zulu\",\r\n      role: \"Database\",\r\n      avatar: liheImg,\r\n      initials: \"TZ\"\r\n    },\r\n    {\r\n      name: \"Mpho Ramokhoase\",\r\n      role: \"Frontend\",\r\n      avatar: mphoImg,\r\n      initials: \"MR\"\r\n    },\r\n    {\r\n      name: \"Nkosinathi Radebe\",\r\n      role: \"Frontend\",\r\n      avatar: nathiImg,\r\n      initials: \"NR\"\r\n    }\r\n  ];\r\n\r\n  return (\r\n    <Box\r\n      minH=\"100vh\"\r\n      backgroundImage={`url(${aboutBg})`}\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundRepeat=\"no-repeat\"\r\n      px={4}\r\n      py={8}\r\n      position=\"relative\"\r\n    >\r\n      {/* Overlay for readability */}\r\n      <Box\r\n        position=\"absolute\"\r\n        top={0}\r\n        left={0}\r\n        width=\"100%\"\r\n        height=\"100%\"\r\n        bg=\"rgba(20, 20, 30, 0.85)\"\r\n        zIndex={0}\r\n      />\r\n      {/* Content */}\r\n      <Box maxW=\"800px\" mx=\"auto\" position=\"relative\" zIndex={1} p={8}>\r\n        <Text fontSize=\"4xl\" fontWeight=\"bold\" textAlign=\"center\" mb={4} color=\"white\">\r\n          About Us\r\n        </Text>\r\n        {/* Mission Statement */}\r\n        <Text fontSize=\"lg\" textAlign=\"center\" mb={4} color=\"gray.200\">\r\n          <b>Our Mission:</b> Empowering communities with affordable solar energy and smart financial management.\r\n        </Text>\r\n        {/* What We Do */}\r\n        <Text fontSize=\"md\" textAlign=\"center\" mb={8} color=\"gray.300\">\r\n          Gridx helps low-income households and small businesses manage energy usage efficiently, track expenses, and stay powered sustainably. We combine technology, finance, and clean energy to create a brighter future for all.\r\n        </Text>\r\n        {/* Core Values */}\r\n        <Box mb={8}>\r\n          <Heading as=\"h3\" size=\"md\" color=\"white\" mb={2} textAlign=\"center\">Our Core Values</Heading>\r\n          <Flex justify=\"center\" wrap=\"wrap\" gap={6}>\r\n            <Box bg=\"gray.600\" borderRadius=\"md\" p={4} minW=\"150px\" textAlign=\"center\" color=\"white\">Sustainability</Box>\r\n            <Box bg=\"gray.600\" borderRadius=\"md\" p={4} minW=\"150px\" textAlign=\"center\" color=\"white\">Community</Box>\r\n            <Box bg=\"gray.600\" borderRadius=\"md\" p={4} minW=\"150px\" textAlign=\"center\" color=\"white\">Innovation</Box>\r\n            <Box bg=\"gray.600\" borderRadius=\"md\" p={4} minW=\"150px\" textAlign=\"center\" color=\"white\">Transparency</Box>\r\n          </Flex>\r\n        </Box>\r\n        {/* Team Streamline */}\r\n        <Text fontSize=\"3xl\" fontWeight=\"bold\" textAlign=\"center\" mb={4} color=\"white\">\r\n          Our Team\r\n        </Text>\r\n        <Flex\r\n          direction=\"row\"\r\n          wrap=\"wrap\"\r\n          justify=\"center\"\r\n          align=\"flex-start\"\r\n          gap={6}\r\n          mb={8}\r\n        >\r\n          {team.map((member) => (\r\n            <Box\r\n              key={member.name}\r\n              bg=\"gray.700\"\r\n              borderRadius=\"2xl\"\r\n              boxShadow=\"lg\"\r\n              p={6}\r\n              display=\"flex\"\r\n              flexDirection=\"column\"\r\n              alignItems=\"center\"\r\n              justifyContent=\"center\"\r\n              minW=\"200px\"\r\n              maxW=\"250px\"\r\n              mx=\"auto\"\r\n              mb={4}\r\n              transition=\"transform 0.2s\"\r\n              _hover={{ transform: 'translateY(-6px) scale(1.04)', boxShadow: '2xl' }}\r\n            >\r\n              {/* Full-size square profile picture */}\r\n              <Box\r\n                width=\"120px\"\r\n                height=\"120px\"\r\n                mb={4}\r\n                borderRadius=\"md\"\r\n                overflow=\"hidden\"\r\n                bg=\"black\"\r\n                border=\"3px solid\"\r\n                borderColor=\"whiteAlpha.400\"\r\n                display=\"flex\"\r\n                alignItems=\"center\"\r\n                justifyContent=\"center\"\r\n              >\r\n                <img\r\n                  src={member.avatar}\r\n                  alt={member.name}\r\n                  style={{\r\n                    width: '100%',\r\n                    height: '100%',\r\n                    objectFit: 'cover',\r\n                    display: 'block'\r\n                  }}\r\n                />\r\n              </Box>\r\n              <Text fontWeight=\"bold\" color=\"white\" fontSize=\"lg\" mb={1} textAlign=\"center\">\r\n                {member.name}\r\n              </Text>\r\n              <Text color=\"gray.300\" fontSize=\"sm\" textAlign=\"center\">\r\n                {member.role}\r\n              </Text>\r\n            </Box>\r\n          ))}\r\n        </Flex>\r\n        {/* Contact Info & Socials */}\r\n        <Box textAlign=\"center\" mb={6}>\r\n          <Heading as=\"h3\" size=\"md\" color=\"white\" mb={2}>Contact Us</Heading>\r\n          <Text color=\"gray.200\" mb={2}>\r\n            Have questions or feedback? Reach out to us!\r\n          </Text>\r\n          <Flex justify=\"center\" gap={4} mb={2}>\r\n            <Button as=\"a\" href=\"mailto:support@gridx.com\" leftIcon={<FaEnvelope />} colorScheme=\"blue\" variant=\"ghost\" size=\"sm\">\r\n              Email\r\n            </Button>\r\n            <Button as=\"a\" href=\"https://twitter.com/\" leftIcon={<FaTwitter />} colorScheme=\"twitter\" variant=\"ghost\" size=\"sm\" target=\"_blank\">\r\n              Twitter\r\n            </Button>\r\n            <Button as=\"a\" href=\"https://facebook.com/\" leftIcon={<FaFacebook />} colorScheme=\"facebook\" variant=\"ghost\" size=\"sm\" target=\"_blank\">\r\n              Facebook\r\n            </Button>\r\n            <Button as=\"a\" href=\"https://instagram.com/\" leftIcon={<FaInstagram />} colorScheme=\"pink\" variant=\"ghost\" size=\"sm\" target=\"_blank\">\r\n              Instagram\r\n            </Button>\r\n          </Flex>\r\n          <Text color=\"gray.400\" fontSize=\"xs\">\r\n            support@gridx.com\r\n          </Text>\r\n        </Box>\r\n        {/* Legal/Privacy */}\r\n        <Box textAlign=\"center\" mb={4}>\r\n          <Text color=\"gray.500\" fontSize=\"xs\">\r\n            By using Gridx, you agree to our <a href=\"/privacy\" style={{ color: \"#63b3ed\" }}>Privacy Policy</a> and <a href=\"/terms\" style={{ color: \"#63b3ed\" }}>Terms of Service</a>.\r\n          </Text>\r\n        </Box>\r\n        {/* Version/Last Updated */}\r\n        <Box textAlign=\"center\" mb={2}>\r\n          <Text color=\"gray.600\" fontSize=\"xs\">\r\n            Version 1.0.0 &nbsp;|&nbsp; Last updated: June 2024\r\n          </Text>\r\n        </Box>\r\n        {/* CTA */}\r\n        <Box textAlign=\"center\" mt={4}>\r\n          <Button colorScheme=\"teal\" size=\"md\" as=\"a\" href=\"/register\">\r\n            Join Gridx Today\r\n          </Button>\r\n        </Box>\r\n        <Box textAlign=\"center\" mt={8}>\r\n          <Button\r\n            as={RouterLink}\r\n            to=\"/terms-of-service\"\r\n            colorScheme=\"blue\"\r\n            variant=\"outline\"\r\n            mr={4}\r\n          >\r\n            Terms of Service\r\n          </Button>\r\n          <Button\r\n            as={RouterLink}\r\n            to=\"/privacy-policy\"\r\n            colorScheme=\"blue\"\r\n            variant=\"outline\"\r\n          >\r\n            Privacy Policy\r\n          </Button>\r\n        </Box>\r\n      </Box>\r\n    </Box>\r\n  );\r\n}\r\n\r\nexport default AboutPage;\r\n","import { useEffect } from 'react';\r\nimport { useNavigate } from 'react-router-dom';\r\n\r\nconst OAuthCallbackHandler = () => {\r\n  const navigate = useNavigate();\r\n\r\n  useEffect(() => {\r\n    const checkAuth = async () => {\r\n      try {\r\n        // Get user data from URL first\r\n        const params = new URLSearchParams(window.location.search);\r\n        const userParam = params.get('user');\r\n        \r\n        if (userParam) {\r\n          try {\r\n            const user = JSON.parse(userParam);\r\n            console.log('Got user from URL:', user);\r\n            localStorage.setItem('user', JSON.stringify(user));\r\n            navigate('/home');\r\n            return;\r\n          } catch (e) {\r\n            console.error('Failed to parse user from URL:', e);\r\n          }\r\n        }\r\n\r\n        // Fallback to session check\r\n        console.log('Checking session...');\r\n        const response = await fetch('http://localhost:5000/api/auth/user', {\r\n          credentials: 'include',\r\n          headers: {\r\n            'Accept': 'application/json',\r\n            'Content-Type': 'application/json'\r\n          }\r\n        });\r\n\r\n        if (response.ok) {\r\n          const data = await response.json();\r\n          console.log('Got user from session:', data);\r\n          if (data.user) {\r\n            localStorage.setItem('user', JSON.stringify(data.user));\r\n            navigate('/home');\r\n            return;\r\n          }\r\n        }\r\n\r\n        // If both methods fail, go to login\r\n        console.log('Auth failed, redirecting to login');\r\n        navigate('/login');\r\n      } catch (error) {\r\n        console.error('Auth check failed:', error);\r\n        navigate('/login');\r\n      }\r\n    };\r\n\r\n    checkAuth();\r\n  }, [navigate]);\r\n\r\n  return <div>Processing Google login...</div>;\r\n};\r\n\r\nexport default OAuthCallbackHandler; ","import { CamelToPascal } from './utility-types';\n\n/**\n * Converts string to kebab case\n *\n * @param {string} string\n * @returns {string} A kebabized string\n */\nexport const toKebabCase = (string: string) =>\n  string.replace(/([a-z0-9])([A-Z])/g, '$1-$2').toLowerCase();\n\n/**\n * Converts string to camel case\n *\n * @param {string} string\n * @returns {string} A camelized string\n */\nexport const toCamelCase = <T extends string>(string: T) =>\n  string.replace(/^([A-Z])|[\\s-_]+(\\w)/g, (match, p1, p2) =>\n    p2 ? p2.toUpperCase() : p1.toLowerCase(),\n  );\n\n/**\n * Converts string to pascal case\n *\n * @param {string} string\n * @returns {string} A pascalized string\n */\nexport const toPascalCase = <T extends string>(string: T): CamelToPascal<T> => {\n  const camelCase = toCamelCase(string);\n\n  return (camelCase.charAt(0).toUpperCase() + camelCase.slice(1)) as CamelToPascal<T>;\n};\n\n/**\n * Merges classes into a single string\n *\n * @param {array} classes\n * @returns {string} A string of classes\n */\nexport const mergeClasses = <ClassType = string | undefined | null>(...classes: ClassType[]) =>\n  classes\n    .filter((className, index, array) => {\n      return (\n        Boolean(className) &&\n        (className as string).trim() !== '' &&\n        array.indexOf(className) === index\n      );\n    })\n    .join(' ')\n    .trim();\n\n/**\n * Check if a component has an accessibility prop\n *\n * @param {object} props\n * @returns {boolean} Whether the component has an accessibility prop\n */\nexport const hasA11yProp = (props: Record<string, any>) => {\n  for (const prop in props) {\n    if (prop.startsWith('aria-') || prop === 'role' || prop === 'title') {\n      return true;\n    }\n  }\n};\n","export default {\n  xmlns: 'http://www.w3.org/2000/svg',\n  width: 24,\n  height: 24,\n  viewBox: '0 0 24 24',\n  fill: 'none',\n  stroke: 'currentColor',\n  strokeWidth: 2,\n  strokeLinecap: 'round',\n  strokeLinejoin: 'round',\n};\n","import { createElement, forwardRef } from 'react';\nimport defaultAttributes from './defaultAttributes';\nimport { IconNode, LucideProps } from './types';\nimport { mergeClasses, hasA11yProp } from '@lucide/shared';\n\ninterface IconComponentProps extends LucideProps {\n  iconNode: IconNode;\n}\n\n/**\n * Lucide icon component\n *\n * @component Icon\n * @param {object} props\n * @param {string} props.color - The color of the icon\n * @param {number} props.size - The size of the icon\n * @param {number} props.strokeWidth - The stroke width of the icon\n * @param {boolean} props.absoluteStrokeWidth - Whether to use absolute stroke width\n * @param {string} props.className - The class name of the icon\n * @param {IconNode} props.children - The children of the icon\n * @param {IconNode} props.iconNode - The icon node of the icon\n *\n * @returns {ForwardRefExoticComponent} LucideIcon\n */\nconst Icon = forwardRef<SVGSVGElement, IconComponentProps>(\n  (\n    {\n      color = 'currentColor',\n      size = 24,\n      strokeWidth = 2,\n      absoluteStrokeWidth,\n      className = '',\n      children,\n      iconNode,\n      ...rest\n    },\n    ref,\n  ) =>\n    createElement(\n      'svg',\n      {\n        ref,\n        ...defaultAttributes,\n        width: size,\n        height: size,\n        stroke: color,\n        strokeWidth: absoluteStrokeWidth ? (Number(strokeWidth) * 24) / Number(size) : strokeWidth,\n        className: mergeClasses('lucide', className),\n        ...(!children && !hasA11yProp(rest) && { 'aria-hidden': 'true' }),\n        ...rest,\n      },\n      [\n        ...iconNode.map(([tag, attrs]) => createElement(tag, attrs)),\n        ...(Array.isArray(children) ? children : [children]),\n      ],\n    ),\n);\n\nexport default Icon;\n","import createLucideIcon from '../createLucideIcon';\nimport { IconNode } from '../types';\n\nexport const __iconNode: IconNode = [\n  ['path', { d: 'M12 8V4H8', key: 'hb8ula' }],\n  ['rect', { width: '16', height: '12', x: '4', y: '8', rx: '2', key: 'enze0r' }],\n  ['path', { d: 'M2 14h2', key: 'vft8re' }],\n  ['path', { d: 'M20 14h2', key: '4cs60a' }],\n  ['path', { d: 'M15 13v2', key: '1xurst' }],\n  ['path', { d: 'M9 13v2', key: 'rq6x2g' }],\n];\n\n/**\n * @component @name Bot\n * @description Lucide SVG icon component, renders SVG Element with children.\n *\n * @preview ![img](data:image/svg+xml;base64,) - https://lucide.dev/icons/bot\n * @see https://lucide.dev/guide/packages/lucide-react - Documentation\n *\n * @param {Object} props - Lucide icons props and any valid SVG attribute\n * @returns {JSX.Element} JSX Element\n *\n */\nconst Bot = createLucideIcon('bot', __iconNode);\n\nexport default Bot;\n","import { createElement, forwardRef } from 'react';\nimport { mergeClasses, toKebabCase, toPascalCase } from '@lucide/shared';\nimport { IconNode, LucideProps } from './types';\nimport Icon from './Icon';\n\n/**\n * Create a Lucide icon component\n * @param {string} iconName\n * @param {array} iconNode\n * @returns {ForwardRefExoticComponent} LucideIcon\n */\nconst createLucideIcon = (iconName: string, iconNode: IconNode) => {\n  const Component = forwardRef<SVGSVGElement, LucideProps>(({ className, ...props }, ref) =>\n    createElement(Icon, {\n      ref,\n      iconNode,\n      className: mergeClasses(\n        `lucide-${toKebabCase(toPascalCase(iconName))}`,\n        `lucide-${iconName}`,\n        className,\n      ),\n      ...props,\n    }),\n  );\n\n  Component.displayName = toPascalCase(iconName);\n\n  return Component;\n};\n\nexport default createLucideIcon;\n","import { Box, Flex, Stack, IconButton, Text, Link as ChakraLink, Button } from '@chakra-ui/react';\r\nimport { FaFacebook, FaTwitter, FaLinkedin, FaInstagram, FaArrowUp } from 'react-icons/fa';\r\nimport { Link as RouterLink } from 'react-router-dom';\r\n\r\nconst Footer = () => {\r\n  return (\r\n    <Box\r\n      bg=\"linear-gradient(90deg, #1c65d1, #2d8dee)\"\r\n      py={6}\r\n      color=\"white\"\r\n      textAlign=\"center\"\r\n    >\r\n      <Flex justify=\"center\" mb={4}>\r\n        <Stack direction=\"row\" spacing={4}>\r\n          <IconButton\r\n            as=\"a\"\r\n            href=\"https://facebook.com\"\r\n            icon={<FaFacebook />}\r\n            aria-label=\"Facebook\"\r\n          />\r\n          <IconButton\r\n            as=\"a\"\r\n            href=\"https://twitter.com\"\r\n            icon={<FaTwitter />}\r\n            aria-label=\"Twitter\"\r\n          />\r\n          <IconButton\r\n            as=\"a\"\r\n            href=\"https://linkedin.com\"\r\n            icon={<FaLinkedin />}\r\n            aria-label=\"LinkedIn\"\r\n          />\r\n          <IconButton\r\n            as=\"a\"\r\n            href=\"https://instagram.com\"\r\n            icon={<FaInstagram />}\r\n            aria-label=\"Instagram\"\r\n          />\r\n        </Stack>\r\n      </Flex>\r\n      <Flex justify=\"center\" mb={4}>\r\n        <Stack direction={{ base: 'column', md: 'row' }} spacing={4}>\r\n          <ChakraLink as={RouterLink} to=\"/about\" color=\"white\" _hover={{ textDecoration: 'underline' }}>About</ChakraLink>\r\n          <ChakraLink as={RouterLink} to=\"/\" color=\"white\" _hover={{ textDecoration: 'underline' }}>Home</ChakraLink>\r\n          <ChakraLink as={RouterLink} to=\"/subscription\" color=\"white\" _hover={{ textDecoration: 'underline' }}>Services</ChakraLink>\r\n          <ChakraLink as={RouterLink} to=\"/team\" color=\"white\" _hover={{ textDecoration: 'underline' }}>Team</ChakraLink>\r\n          <ChakraLink as={RouterLink} to=\"/support\" color=\"white\" _hover={{ textDecoration: 'underline' }}>Contact</ChakraLink>\r\n          <ChakraLink as={RouterLink} to=\"/terms-of-service\" color=\"white\" _hover={{ textDecoration: 'underline' }}>Terms of Service</ChakraLink>\r\n          <ChakraLink as={RouterLink} to=\"/privacy-policy\" color=\"white\" _hover={{ textDecoration: 'underline' }}>Privacy Policy</ChakraLink>\r\n        </Stack>\r\n      </Flex>\r\n      <Text fontSize=\"sm\" mb={2} color=\"white\" textShadow=\"1px 1px 2px rgba(0, 0, 0, 0.5)\">©2025 | All Rights Reserved · Powered by GridX</Text>\r\n      <Text fontSize=\"xs\" mb={4} color=\"white\" textShadow=\"1px 1px 2px rgba(0, 0, 0, 0.5)\">Innovating Energy Solutions for a Sustainable Tomorrow</Text>\r\n      <Button\r\n        size=\"sm\"\r\n        onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}\r\n        rightIcon={<FaArrowUp />}\r\n        variant=\"outline\"\r\n        colorScheme=\"whiteAlpha\"\r\n      >\r\n        Back to Top\r\n      </Button>\r\n    </Box>\r\n  );\r\n};\r\n\r\nexport default Footer; ","import React, { useState, useEffect, useMemo } from 'react';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { auth } from '../services/api';\r\n// eslint-disable-next-line no-unused-vars\r\nimport { useDashboard } from '../context/DashboardContext';\r\nimport ErrorBoundary from '../components/ErrorBoundary';\r\nimport { motion } from 'framer-motion';\r\nimport { Bot } from 'lucide-react';\r\nimport { Link } from 'react-router-dom';\r\nimport Footer from '../components/Footer';\r\n\r\n// Import the video\r\nimport backgroundVideo from '../assets/videos/Slowed-GridX-Video.mp4';\r\n\r\n// Import Chakra UI Components\r\nimport {\r\n  Box,\r\n  Flex,\r\n  Heading,\r\n  Text,\r\n  Button,\r\n  SimpleGrid,\r\n  Icon,\r\n  useColorModeValue,\r\n  Container,\r\n  Spinner,\r\n  useToast,\r\n  IconButton,\r\n  VStack,\r\n  Fade,\r\n  Input,\r\n  Grid\r\n} from '@chakra-ui/react';\r\n\r\n// Import Icons\r\nimport {\r\n  FaSolarPanel,\r\n  FaBatteryFull,\r\n  FaPlug,\r\n  FaTree,\r\n  FaCoins,\r\n  FaTools,\r\n  FaLightbulb,\r\n  FaHandshake,\r\n  FaUsers,\r\n  FaCreditCard,\r\n  FaRegLightbulb,\r\n  FaRegSun,\r\n  FaRegMoon,\r\n  FaSignOutAlt,\r\n  FaUser\r\n} from 'react-icons/fa';\r\n\r\n// Import useColorMode hook\r\nimport { useColorMode } from '@chakra-ui/react';\r\n\r\n// Import the image\r\nimport aboutBg from '../assets/images/About_Page_IMG.png';\r\n\r\n// Constants and utility functions\r\nconst getTimeOfDay = () => {\r\n  const hour = new Date().getHours();\r\n  return hour < 12 ? 'morning' : hour < 18 ? 'afternoon' : 'evening';\r\n};\r\n\r\nconst GLASS_STYLES = {\r\n  light: {\r\n    backdropFilter: 'blur(10px)',\r\n    backgroundColor: 'rgba(255, 255, 255, 0.85)',\r\n    border: '1px solid rgba(255, 255, 255, 0.3)',\r\n    boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.2)',\r\n  },\r\n  dark: {\r\n    backdropFilter: 'blur(10px)',\r\n    backgroundColor: 'rgba(17, 25, 40, 0.75)',\r\n    border: '1px solid rgba(255, 255, 255, 0.1)',\r\n    boxShadow: '0 8px 32px 0 rgba(31, 38, 135, 0.37)',\r\n  }\r\n};\r\n\r\nfunction HomePage() {\r\n  // Hooks and state\r\n  const navigate = useNavigate();\r\n  const toast = useToast();\r\n  const { colorMode, toggleColorMode } = useColorMode();\r\n  const newsletterBg = useColorModeValue('whiteAlpha.900', 'gray.800');\r\n  const bgColor = useColorModeValue('gray.50', 'gray.900');\r\n  const textColor = useColorModeValue('gray.800', 'gray.400');\r\n  const headingColor = useColorModeValue('gray.900', 'white');\r\n  const spinnerColor = useColorModeValue('blue.500', 'blue.300');\r\n  const glassStyles = useColorModeValue(GLASS_STYLES.light, GLASS_STYLES.dark);\r\n  const user = auth.getCurrentUser();\r\n  console.log('HomePage rendering: User is', user ? 'logged in' : 'not logged in');\r\n  // const { currentThemeConfig } = useDashboard(); // Remove or comment out this line\r\n\r\n  const [isLoadingGreeting, setIsLoadingGreeting] = useState(true);\r\n  const [aiGreeting, setAiGreeting] = useState(null);\r\n  const [greetingError, setGreetingError] = useState(false);\r\n  const [currentTipIndex, setCurrentTipIndex] = useState(0);\r\n\r\n  // Memoized data configs\r\n  const { navItems, solarTips } = useMemo(() => ({\r\n    navItems: [\r\n    {\r\n      icon: FaSolarPanel,\r\n      title: 'Dashboard',\r\n      description: 'View your power usage and financial summary',\r\n      path: '/dashboard',\r\n      colorScheme: 'blue'\r\n    },\r\n    {\r\n      icon: FaBatteryFull,\r\n      title: 'Profile',\r\n      description: 'Manage your personal information',\r\n      path: '/profile',\r\n      colorScheme: 'teal'\r\n    },\r\n    {\r\n      icon: FaPlug,\r\n      title: 'Top Up',\r\n      description: 'Add credit to your power account',\r\n      path: '/top-up',\r\n      colorScheme: 'green'\r\n    },\r\n    {\r\n      icon: FaCoins,\r\n      title: 'Expenses',\r\n      description: 'Track your power expenses',\r\n      path: '/expenses',\r\n      colorScheme: 'purple'\r\n    },\r\n    {\r\n      icon: FaRegLightbulb,\r\n      title: 'Notifications',\r\n      description: 'View your alerts and updates',\r\n      path: '/notifications',\r\n      colorScheme: 'orange'\r\n    },\r\n    {\r\n      icon: FaTools,\r\n      title: 'Settings',\r\n      description: 'Customize your preferences',\r\n      path: '/settings',\r\n      colorScheme: 'gray'\r\n    },\r\n    {\r\n      icon: FaTree,\r\n      title: 'Impact',\r\n      description: 'See your environmental impact',\r\n      path: '/impact',\r\n      colorScheme: 'teal'\r\n    },\r\n    {\r\n      icon: FaLightbulb,\r\n      title: 'Support',\r\n      description: 'Get help and find answers',\r\n      path: '/support',\r\n      colorScheme: 'blue'\r\n    },\r\n    {\r\n      icon: FaRegSun,\r\n      title: 'Forum',\r\n      description: 'Join the community discussion',\r\n      path: '/forum',\r\n      colorScheme: 'purple'\r\n    },\r\n    {\r\n      icon: FaHandshake,\r\n      title: 'Refer & Earn',\r\n      description: 'Invite friends and get rewards',\r\n      path: '/refer',\r\n      colorScheme: 'orange'\r\n    },\r\n    {\r\n      icon: FaUsers,\r\n      title: 'Group Buying',\r\n      description: 'Join or create group solar purchases and save',\r\n      path: '/group-buying',\r\n      colorScheme: 'purple'\r\n    },\r\n    {\r\n      icon: FaCreditCard,\r\n      title: 'Subscriptions',\r\n      description: 'Manage your energy subscription plans',\r\n      path: '/subscription',\r\n      colorScheme: 'blue'\r\n    },\r\n    {\r\n      icon: Bot,\r\n      title: 'AI Suggestions',\r\n      description: 'Get smart tips from our AI to save energy and manage finances',\r\n      path: '/ai-suggestions',\r\n      colorScheme: 'purple'\r\n    },\r\n    {\r\n      icon: FaUser,\r\n      title: 'Profile Details',\r\n      description: 'Update your personal information',\r\n      path: '/personal-user',\r\n      colorScheme: 'blue'\r\n    }\r\n    ],\r\n    solarTips: [\r\n    'Consider running high-consumption appliances during peak sunlight hours.',\r\n    'Your battery storage is optimized for evening usage patterns.',\r\n    'Did you know opening curtains can reduce lighting costs by up to 30%?',\r\n    'Current weather patterns suggest ideal solar generation today.'\r\n    ]\r\n  }), []);\r\n\r\n  // Effects\r\n  useEffect(() => {\r\n    console.log('Checking user authentication in useEffect');\r\n    if (!user) {\r\n      toast({\r\n        title: 'Authentication Required',\r\n        description: 'Please log in to access this page',\r\n        status: 'warning',\r\n        duration: 3000,\r\n        isClosable: true,\r\n      });\r\n      setTimeout(() => navigate('/login'), 1000);\r\n    }\r\n  }, [user, navigate, toast]);\r\n\r\n  useEffect(() => {\r\n    const mockGreetingApi = async () => {\r\n      try {\r\n        console.log('Fetching greeting for user:', user);\r\n        // Simulate a successful response for testing; remove randomness\r\n        const response = {\r\n          message: `🌞 Good ${getTimeOfDay()}, ${user?.name || \"Valued User\"}! ` +\r\n                   `Here's your personalized energy tip: ${solarTips[currentTipIndex]}`\r\n        };\r\n        setAiGreeting(response.message);\r\n        setGreetingError(false);\r\n        setIsLoadingGreeting(false);\r\n      } catch (error) {\r\n        console.error('Error fetching greeting:', error);\r\n        setGreetingError(true);\r\n        setAiGreeting('An error occurred while loading the greeting. Please try again later.');\r\n        setIsLoadingGreeting(false);\r\n      }\r\n    };\r\n\r\n    if (user) {\r\n      mockGreetingApi();\r\n    } else {\r\n      setAiGreeting('Please log in to see personalized content.');\r\n    }\r\n  }, [user, currentTipIndex, solarTips]);\r\n\r\n  useEffect(() => {\r\n    const interval = setInterval(() => {\r\n      setCurrentTipIndex((prevIndex) => \r\n        prevIndex === solarTips.length - 1 ? 0 : prevIndex + 1\r\n      );\r\n    }, 5000);\r\n\r\n    return () => clearInterval(interval);\r\n  }, [solarTips.length]);\r\n\r\n  // Handlers\r\n  const handleLogout = () => {\r\n    auth.logout();\r\n    navigate('/login');\r\n  };\r\n\r\n  // Render helpers\r\n  const renderHeader = () => (\r\n          <Flex justify=\"space-between\" align=\"flex-start\" mb={8} direction={{ base: 'column', md: 'row' }} gap={4}>\r\n            <Box flex=\"1\">\r\n        <Heading as=\"h1\" size=\"xl\" color={headingColor} mb={2}>\r\n          Welcome, {user.name}! \r\n              </Heading>\r\n              \r\n              {isLoadingGreeting ? (\r\n                <Flex align=\"center\" mt={2}>\r\n            <Spinner size=\"sm\" mr={2} color={spinnerColor} />\r\n            <Text fontSize=\"sm\" color={textColor}>\r\n                    Crafting your energy insights...\r\n                  </Text>\r\n                </Flex>\r\n              ) : aiGreeting ? (\r\n                <Fade in={true} key={currentTipIndex}>\r\n                  <Text \r\n                    fontSize=\"lg\" \r\n              color={headingColor} \r\n                    fontWeight=\"medium\" \r\n                    mt={2}\r\n                    transition=\"opacity 0.5s ease-in-out\"\r\n                  >\r\n                    {aiGreeting}\r\n                  </Text>\r\n                </Fade>\r\n              ) : greetingError ? (\r\n          <Text fontSize=\"md\" color=\"orange.600\" mt={2}>\r\n            ⚠️ Connection Issue: {solarTips[currentTipIndex]}\r\n                </Text>\r\n              ) : null}\r\n            </Box>\r\n\r\n            <Flex align=\"center\" gap={4} mt={{ base: 2, md: 0 }}>\r\n              <VStack align=\"flex-end\" spacing={1}>\r\n          <Text fontSize=\"sm\" color={textColor} textAlign=\"right\">\r\n                  {new Date().toLocaleDateString('en-US', { \r\n                    weekday: 'long', \r\n                    month: 'long', \r\n                    day: 'numeric' \r\n                  })}\r\n                </Text>\r\n                <IconButton\r\n                  aria-label=\"Toggle Theme\"\r\n                  icon={colorMode === 'light' ? <FaRegMoon /> : <FaRegSun />}\r\n                  onClick={toggleColorMode}\r\n                  variant=\"ghost\"\r\n                  size=\"sm\"\r\n            color={textColor}\r\n                />\r\n              </VStack>\r\n            </Flex>\r\n          </Flex>\r\n  );\r\n\r\n  const renderNavGrid = () => (\r\n    <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={6} mt={8}>\r\n      {navItems.map((item) => (\r\n        <motion.div\r\n          key={item.title}\r\n          initial={{ opacity: 0, y: 50 }}\r\n          animate={{ opacity: 1, y: 0 }}\r\n          transition={{ duration: 0.5 }}\r\n          whileHover={{ scale: 1.05, boxShadow: '0px 10px 20px rgba(0, 0, 0, 0.1)' }}\r\n        >\r\n          <Box\r\n            p={6}\r\n            borderWidth=\"1px\"\r\n            borderRadius=\"md\"\r\n            bg={glassStyles.backgroundColor}\r\n            boxShadow=\"lg\"\r\n            _hover={{ boxShadow: 'xl' }}\r\n            display=\"flex\"\r\n            flexDirection=\"column\"\r\n            alignItems=\"center\"\r\n            justifyContent=\"center\"\r\n            height=\"200px\"  // Consistent height for cards\r\n            backdropFilter=\"blur(10px)\"\r\n          >\r\n            <Flex align=\"center\" justify=\"center\">\r\n              <Icon as={item.icon} boxSize={8} color={item.colorScheme + '.500'} />\r\n              <Heading size=\"md\" color={headingColor} ml={2}>{item.title}</Heading>\r\n            </Flex>\r\n            <Text color={textColor} mt={2} textAlign=\"center\">\r\n              {item.description}\r\n            </Text>\r\n            <Button\r\n              mt={4}\r\n              colorScheme={item.colorScheme}\r\n              as={Link}\r\n              to={item.path}\r\n              size=\"md\"\r\n              width=\"full\"\r\n            >\r\n              Go to {item.title}\r\n            </Button>\r\n          </Box>\r\n        </motion.div>\r\n      ))}\r\n    </SimpleGrid>\r\n  );\r\n\r\n  if (!user) {\r\n    return (\r\n      <Flex minH=\"100vh\" align=\"center\" justify=\"center\" bg={bgColor}>\r\n        <Spinner size=\"xl\" color={spinnerColor} />\r\n      </Flex>\r\n    );\r\n  }\r\n\r\n  return (\r\n    <ErrorBoundary fallback={<Text>Error loading page. Please try refreshing. Check console for details.</Text>}>\r\n      <Box\r\n        minH=\"100vh\"\r\n        backgroundImage={`url(${aboutBg})`}\r\n        backgroundSize=\"cover\"\r\n        backgroundPosition=\"center\"\r\n        backgroundRepeat=\"no-repeat\"\r\n        px={4}\r\n        py={8}\r\n        overflow=\"auto\"\r\n      >\r\n        {/* Video Background */}\r\n        <Box\r\n          position=\"fixed\"\r\n          top=\"0\"\r\n          left=\"0\"\r\n          width=\"100%\"\r\n          height=\"100%\"\r\n          zIndex=\"0\"\r\n          overflow=\"hidden\"\r\n        >\r\n          <video\r\n            autoPlay\r\n            muted\r\n            loop\r\n            playsInline\r\n            style={{\r\n              width: '100%',\r\n              height: '100%',\r\n              objectFit: 'cover',\r\n              position: 'absolute',\r\n              top: '50%',\r\n              left: '50%',\r\n              transform: 'translate(-50%, -50%)',\r\n            }}\r\n          >\r\n            <source src={backgroundVideo} type=\"video/mp4\" />\r\n          </video>\r\n          {/* Overlay to ensure content readability */}\r\n          <Box\r\n            position=\"absolute\"\r\n            top=\"0\"\r\n            left=\"0\"\r\n            width=\"100%\"\r\n            height=\"100%\"\r\n            bg=\"rgba(0, 0, 0, 0.5)\"\r\n            zIndex=\"1\"\r\n          />\r\n        </Box>\r\n\r\n        {/* Main Content - Add relative positioning and z-index */}\r\n        <Box position=\"relative\" zIndex=\"2\" pb={20}>\r\n          <Container maxW=\"container.xl\" py={8}>\r\n            {renderHeader()}\r\n            {renderNavGrid()}\r\n            \r\n            {/* Newsletter Signup Section */}\r\n            <Box as=\"section\" py={4} px={6} bg={newsletterBg} borderRadius=\"md\" boxShadow=\"sm\" mt={8} borderWidth=\"0\">\r\n              <Grid templateColumns={{ base: '1fr', md: '1fr 1fr' }} gap={4} justify=\"center\" align=\"center\">\r\n                <Input\r\n                  type=\"email\"\r\n                  placeholder=\"Enter your email\"\r\n                  variant=\"outline\"\r\n                  size=\"md\"\r\n                  w=\"100%\"\r\n                  id=\"newsletterEmail\"\r\n                />\r\n                <Button \r\n                  colorScheme=\"blue\" \r\n                  onClick={() => {\r\n                    const emailInput = document.getElementById('newsletterEmail');\r\n                    if (emailInput && emailInput.value.includes('@')) {\r\n                      toast({\r\n                        title: 'Subscription Successful!',\r\n                        description: 'You have been subscribed. Check your email for confirmation.',\r\n                        status: 'success',\r\n                        duration: 5000,\r\n                        isClosable: true\r\n                      });\r\n                    } else {\r\n                      toast({\r\n                        title: 'Error',\r\n                        description: 'Please enter a valid email address.',\r\n                        status: 'error',\r\n                        duration: 3000,\r\n                        isClosable: true\r\n                      });\r\n                    }\r\n                  }}\r\n                >\r\n                  Subscribe\r\n                </Button>\r\n              </Grid>\r\n            </Box>\r\n            \r\n            {/* Moved Logout Button */}\r\n            <Box textAlign=\"center\" mt={8}>\r\n              <Button\r\n                colorScheme=\"red\"\r\n                onClick={handleLogout}\r\n                leftIcon={<FaSignOutAlt />}\r\n                size=\"lg\"\r\n              >\r\n                Logout\r\n              </Button>\r\n            </Box>\r\n          </Container>\r\n          {/* Ensure Footer is rendered with proper styling */}\r\n          <Box mt={8} position=\"relative\" zIndex=\"3\" width=\"100%\" bg=\"transparent\">\r\n            <Footer />\r\n          </Box>\r\n        </Box>\r\n      </Box>\r\n    </ErrorBoundary>\r\n  );\r\n}\r\n\r\nexport default HomePage;\r\n","'use client';\nimport { jsx } from 'react/jsx-runtime';\n\nconst VALID_VALUES = /* @__PURE__ */ new Set([\"dark\", \"light\", \"system\"]);\nfunction normalize(initialColorMode) {\n  let value = initialColorMode;\n  if (!VALID_VALUES.has(value))\n    value = \"light\";\n  return value;\n}\nfunction getScriptSrc(props = {}) {\n  const {\n    initialColorMode = \"light\",\n    type = \"localStorage\",\n    storageKey: key = \"chakra-ui-color-mode\"\n  } = props;\n  const init = normalize(initialColorMode);\n  const isCookie = type === \"cookie\";\n  const cookieScript = `(function(){try{var a=function(o){var l=\"(prefers-color-scheme: dark)\",v=window.matchMedia(l).matches?\"dark\":\"light\",e=o===\"syst