Name);\n    const styles = useModalStyles();\n    const footerStyles = defineStyle({\n      display: \"flex\",\n      alignItems: \"center\",\n      justifyContent: \"flex-end\",\n      ...styles.footer\n    });\n    return /* @__PURE__ */ jsx(\n      chakra.footer,\n      {\n        ref,\n        ...rest,\n        __css: footerStyles,\n        className: _className\n      }\n    );\n  }\n);\nModalFooter.displayName = \"ModalFooter\";\n\nexport { ModalFooter };\n","import React, { useState, useEffect } from 'react';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { auth } from '../services/api'; // Assuming auth service is still used\r\nimport { FaArrowLeft } from 'react-icons/fa'; // Import FaArrowLeft\r\n\r\n// Import Chakra UI Components\r\nimport {\r\n  Box,\r\n  Flex,\r\n  Heading,\r\n  Text,\r\n  FormControl,\r\n  FormLabel,\r\n  Input,\r\n  Button,\r\n  VStack,\r\n  useToast, // For displaying messages\r\n  useColorModeValue, // For light/dark mode styling\r\n  Spinner, // Added Spinner for loading state\r\n  HStack, // Added HStack for horizontal back button layout\r\n  Divider,\r\n  Alert,\r\n  AlertIcon,\r\n  AlertTitle,\r\n  AlertDescription,\r\n  useDisclosure,\r\n  Modal,\r\n  ModalOverlay,\r\n  ModalContent,\r\n  ModalHeader,\r\n  ModalBody,\r\n  ModalFooter,\r\n  ModalCloseButton,\r\n  Select\r\n} from '@chakra-ui/react';\r\n\r\nfunction TopUpPage() {\r\n  const navigate = useNavigate();\r\n  const toast = useToast();\r\n  const { isOpen, onOpen, onClose } = useDisclosure();\r\n\r\n  // State for form fields and balance\r\n  const [currentBalance, setCurrentBalance] = useState(150.50); // Mock initial balance\r\n  const [amount, setAmount] = useState(''); // Amount to top-up\r\n  const [promoCode, setPromoCode] = useState(''); // Optional promo code\r\n  const [voucherCode, setVoucherCode] = useState(''); // Optional voucher code\r\n  const [isProcessing, setIsProcessing] = useState(false); // Loading state for top-up button\r\n\r\n  // New state for Auto-Top-Up\r\n  const [isAutoTopUpEnabled, setIsAutoTopUpEnabled] = useState(false);\r\n  const [minBalance, setMinBalance] = useState('');\r\n  const [autoTopUpAmount, setAutoTopUpAmount] = useState('');\r\n  const [autoTopUpFrequency, setAutoTopUpFrequency] = useState('weekly');\r\n\r\n  const [transactionType, setTransactionType] = useState('topup'); // New state for transaction type\r\n\r\n  const user = auth.getCurrentUser(); // Get current user data\r\n\r\n  // Chakra UI hook for dynamic colors based on color mode\r\n  const bgColor = useColorModeValue('gray.50', 'gray.800');\r\n  const textColor = useColorModeValue('gray.700', 'gray.200');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const buttonColorScheme = useColorModeValue('green', 'teal'); // Use green/teal for top-up\r\n  const spinnerColor = useColorModeValue('blue.500', 'blue.300');\r\n\r\n  // Styles for the glassmorphism effect on the form Box\r\n  const glassmorphismBoxStyles = {\r\n    bg: useColorModeValue('rgba(255, 255, 255, 0.15)', 'rgba(26, 32, 44, 0.15)'), // Semi-transparent background\r\n    backdropFilter: 'blur(10px)', // Blur effect\r\n    boxShadow: useColorModeValue('lg', 'dark-lg'), // Shadow for depth\r\n    borderRadius: 'lg', // Rounded corners\r\n  };\r\n\r\n  // Basic check if user data is available. ProtectedRoute handles the main redirection,\r\n  // but this can help if the user object is null for some reason after landing here.\r\n  useEffect(() => {\r\n      if (!user) {\r\n          navigate('/login');\r\n      }\r\n  }, [user, navigate]); // Effect runs on component mount and if user/navigate changes\r\n\r\n  // Handler for Auto-Top-Up settings\r\n  const handleAutoTopUpSave = () => {\r\n    if (!minBalance || !autoTopUpAmount) {\r\n      toast({\r\n        title: 'Missing Information',\r\n        description: 'Please fill in all required fields for Auto Top-Up.',\r\n        status: 'warning',\r\n        duration: 3000,\r\n        isClosable: true,\r\n      });\r\n      return;\r\n    }\r\n\r\n    // Simulate saving Auto-Top-Up settings\r\n    setIsProcessing(true);\r\n    setTimeout(() => {\r\n      setIsProcessing(false);\r\n      setIsAutoTopUpEnabled(true);\r\n      onClose();\r\n      toast({\r\n        title: 'Auto Top-Up Enabled',\r\n        description: `Your account will be topped up with R${autoTopUpAmount} when balance falls below R${minBalance}.`,\r\n        status: 'success',\r\n        duration: 5000,\r\n        isClosable: true,\r\n      });\r\n    }, 1500);\r\n  };\r\n\r\n  // Handler for the Top-Up button click\r\n  const handleTopUp = async (e) => {\r\n    e.preventDefault();\r\n\r\n    const topUpAmount = parseFloat(amount);\r\n    if (isNaN(topUpAmount) || topUpAmount <= 0) {\r\n        toast({\r\n            title: 'Invalid Amount',\r\n            description: 'Please enter a valid positive amount.',\r\n            status: 'warning',\r\n            duration: 3000,\r\n            isClosable: true,\r\n        });\r\n        return;\r\n    }\r\n\r\n    setIsProcessing(true);\r\n\r\n    // Log the transaction type along with other details\r\n    console.log('Attempting transaction:', { \r\n        type: transactionType,\r\n        amount, \r\n        promoCode, \r\n        voucherCode \r\n    });\r\n\r\n    // Simulate an API call delay\r\n    await new Promise(resolve => setTimeout(resolve, 1500));\r\n\r\n    // Simulate successful transaction and update balance\r\n    const newBalance = currentBalance + topUpAmount;\r\n    setCurrentBalance(newBalance);\r\n\r\n    // Clear form fields after successful transaction\r\n    setAmount('');\r\n    setPromoCode('');\r\n    setVoucherCode('');\r\n\r\n    toast({\r\n        title: `${transactionType === 'topup' ? 'Top-Up' : 'Recharge'} Successful!`,\r\n        description: `Your new balance is R${newBalance.toFixed(2)}.`,\r\n        status: 'success',\r\n        duration: 5000,\r\n        isClosable: true,\r\n    });\r\n\r\n    setIsProcessing(false); // Reset loading state\r\n  };\r\n\r\n  // Render loading spinner if user is being checked (though ProtectedRoute handles the redirect)\r\n  if (!user) {\r\n        return (\r\n            <Flex minH=\"100vh\" align=\"center\" justify=\"center\" bg={bgColor}>\r\n                <Spinner size=\"xl\" color={spinnerColor} />\r\n            </Flex>\r\n        );\r\n    }\r\n\r\n  return (\r\n    <Flex\r\n      minH=\"100vh\"\r\n      align=\"center\"\r\n      justify=\"center\"\r\n      p={4}\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\" // Your gradient\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\" // Fix background during scroll\r\n      position=\"relative\" // Needed for the pseudo-element overlay\r\n      _before={{ // Semi-transparent overlay for readability\r\n          content: '\"\"',\r\n          position: 'absolute',\r\n          top: 0,\r\n          left: 0,\r\n          right: 0,\r\n          bottom: 0,\r\n          bg: 'rgba(0, 0, 0, 0.5)', // Dark overlay (adjust opacity as needed)\r\n          zIndex: 1, // Ensure overlay is behind content\r\n      }}\r\n    >\r\n      <Box\r\n        maxW=\"md\"\r\n        w=\"full\"\r\n        {...glassmorphismBoxStyles} // Apply glassmorphism styles here\r\n        boxShadow=\"md\" // Keep or adjust shadow as needed\r\n        borderRadius=\"lg\" // Keep or adjust border radius\r\n        p={6}\r\n        textAlign=\"center\"\r\n        position=\"relative\" // Needed for zIndex\r\n        zIndex={2} // Ensure content is above overlay\r\n      >\r\n         {/* Back to Home Button in HStack */}\r\n         <HStack justify=\"space-between\" w=\"full\" mb={8} align=\"center\">\r\n             <Button\r\n               leftIcon={<FaArrowLeft />}\r\n               variant=\"ghost\"\r\n               onClick={() => navigate('/home')}\r\n               color={headingColor}\r\n             >\r\n                Back to Home\r\n             </Button>\r\n         </HStack>\r\n\r\n        {/* Main Heading placed below the HStack */}\r\n        <Heading as=\"h2\" size=\"xl\" mb={6} color={headingColor} textAlign=\"center\">\r\n          Top-Up / Recharge\r\n        </Heading>\r\n\r\n        {/* Current Balance Display */}\r\n        <Box mb={6}>\r\n            <Text fontSize=\"md\" color={textColor}>Current Energy Credit Balance:</Text>\r\n            <Text fontSize=\"3xl\" fontWeight=\"bold\" color={textColor}>\r\n                R{currentBalance.toFixed(2)} {/* Display balance formatted */}\r\n            </Text>\r\n        </Box>\r\n\r\n\r\n        <VStack as=\"form\" spacing={4} onSubmit={handleTopUp} noValidate>\r\n          {/* Transaction Type Selection */}\r\n          <FormControl id=\"transaction-type\">\r\n            <FormLabel>Transaction Type</FormLabel>\r\n            <Select\r\n              value={transactionType}\r\n              onChange={(e) => setTransactionType(e.target.value)}\r\n            >\r\n              <option value=\"topup\">Top-Up</option>\r\n              <option value=\"recharge\">Recharge</option>\r\n            </Select>\r\n          </FormControl>\r\n\r\n          {/* Amount Input */}\r\n          <FormControl id=\"top-up-amount\">\r\n            <FormLabel>Amount (ZAR)</FormLabel>\r\n            <Input\r\n              type=\"number\" // Use number type for currency\r\n              placeholder=\"Enter amount\"\r\n              value={amount}\r\n              onChange={(e) => setAmount(e.target.value)}\r\n              step=\"0.01\" // Allow decimal values\r\n              min=\"0\" // Ensure positive amount\r\n            />\r\n          </FormControl>\r\n\r\n          {/* Optional Promo Code Input */}\r\n          <FormControl id=\"promo-code\">\r\n            <FormLabel>Promo Code (Optional)</FormLabel>\r\n            <Input\r\n              type=\"text\"\r\n              placeholder=\"Enter promo code\"\r\n              value={promoCode}\r\n              onChange={(e) => setPromoCode(e.target.value)}\r\n            />\r\n          </FormControl>\r\n\r\n           {/* Optional Voucher Code Input */}\r\n          <FormControl id=\"voucher-code\">\r\n            <FormLabel>Voucher Code (Optional)</FormLabel>\r\n            <Input\r\n              type=\"text\"\r\n              placeholder=\"Enter voucher code\"\r\n              value={voucherCode}\r\n              onChange={(e) => setVoucherCode(e.target.value)}\r\n            />\r\n          </FormControl>\r\n\r\n\r\n          {/* Top-Up Button */}\r\n          <Button\r\n            type=\"submit\"\r\n            colorScheme={buttonColorScheme}\r\n            size=\"lg\"\r\n            fontSize=\"md\"\r\n            isLoading={isProcessing}\r\n            loadingText=\"Processing...\"\r\n            w=\"full\"\r\n            mt={4}\r\n          >\r\n            {transactionType === 'topup' ? 'Top-Up Now' : 'Recharge Now'}\r\n          </Button>\r\n        </VStack>\r\n\r\n        {/* Divider */}\r\n        <Divider my={6} />\r\n\r\n        {/* Auto Top-Up Section */}\r\n        <Box>\r\n          <Heading as=\"h3\" size=\"md\" mb={4} color={headingColor}>\r\n            Auto Top-Up Settings\r\n          </Heading>\r\n          \r\n          {isAutoTopUpEnabled ? (\r\n            <Alert status=\"success\" mb={4}>\r\n              <AlertIcon />\r\n              <Box>\r\n                <AlertTitle>Auto Top-Up is Active</AlertTitle>\r\n                <AlertDescription>\r\n                  Your account will be topped up with R{autoTopUpAmount} when balance falls below R{minBalance}.\r\n                </AlertDescription>\r\n              </Box>\r\n            </Alert>\r\n          ) : (\r\n            <Text color={textColor} mb={4}>\r\n              Enable automatic top-ups to ensure you never run out of credit.\r\n            </Text>\r\n          )}\r\n\r\n          <Button\r\n            colorScheme={isAutoTopUpEnabled ? \"red\" : \"green\"}\r\n            variant=\"outline\"\r\n            w=\"full\"\r\n            onClick={onOpen}\r\n          >\r\n            {isAutoTopUpEnabled ? \"Modify Auto Top-Up\" : \"Set Up Auto Top-Up\"}\r\n          </Button>\r\n        </Box>\r\n\r\n        {/* Auto Top-Up Modal */}\r\n        <Modal isOpen={isOpen} onClose={onClose}>\r\n          <ModalOverlay />\r\n          <ModalContent>\r\n            <ModalHeader>Auto Top-Up Settings</ModalHeader>\r\n            <ModalCloseButton />\r\n            <ModalBody>\r\n              <VStack spacing={4}>\r\n                <FormControl>\r\n                  <FormLabel>Minimum Balance (R)</FormLabel>\r\n                  <Input\r\n                    type=\"number\"\r\n                    placeholder=\"e.g., 100\"\r\n                    value={minBalance}\r\n                    onChange={(e) => setMinBalance(e.target.value)}\r\n                  />\r\n                </FormControl>\r\n\r\n                <FormControl>\r\n                  <FormLabel>Auto Top-Up Amount (R)</FormLabel>\r\n                  <Input\r\n                    type=\"number\"\r\n                    placeholder=\"e.g., 200\"\r\n                    value={autoTopUpAmount}\r\n                    onChange={(e) => setAutoTopUpAmount(e.target.value)}\r\n                  />\r\n                </FormControl>\r\n\r\n                <FormControl>\r\n                  <FormLabel>Frequency</FormLabel>\r\n                  <Select\r\n                    value={autoTopUpFrequency}\r\n                    onChange={(e) => setAutoTopUpFrequency(e.target.value)}\r\n                  >\r\n                    <option value=\"weekly\">Weekly</option>\r\n                    <option value=\"monthly\">Monthly</option>\r\n                    <option value=\"quarterly\">Quarterly</option>\r\n                  </Select>\r\n                </FormControl>\r\n              </VStack>\r\n            </ModalBody>\r\n\r\n            <ModalFooter>\r\n              <Button variant=\"ghost\" mr={3} onClick={onClose}>\r\n                Cancel\r\n              </Button>\r\n              <Button\r\n                colorScheme=\"green\"\r\n                onClick={handleAutoTopUpSave}\r\n                isLoading={isProcessing}\r\n              >\r\n                Save Settings\r\n              </Button>\r\n            </ModalFooter>\r\n          </ModalContent>\r\n        </Modal>\r\n      </Box>\r\n    </Flex>\r\n  );\r\n}\r\n\r\nexport default TopUpPage;\r\n","'use client';\nimport { jsx } from 'react/jsx-runtime';\nimport { Modal } from './modal.mjs';\nimport { ModalContent } from './modal-content.mjs';\nexport { ModalBody as AlertDialogBody } from './modal-body.mjs';\nexport { ModalCloseButton as AlertDialogCloseButton } from './modal-close-button.mjs';\nexport { ModalFooter as AlertDialogFooter } from './modal-footer.mjs';\nexport { ModalHeader as AlertDialogHeader } from './modal-header.mjs';\nexport { ModalOverlay as AlertDialogOverlay } from './modal-overlay.mjs';\nimport { forwardRef } from '../system/forward-ref.mjs';\n\nfunction AlertDialog(props) {\n  const { leastDestructiveRef, ...rest } = props;\n  return /* @__PURE__ */ jsx(Modal, { ...rest, initialFocusRef: leastDestructiveRef });\n}\nconst AlertDialogContent = forwardRef(\n  (props, ref) => /* @__PURE__ */ jsx(ModalContent, { ref, role: \"alertdialog\", ...props })\n);\n\nexport { AlertDialog, AlertDialogContent };\n","'use client';\nimport { jsx } from 'react/jsx-runtime';\nimport { Children } from 'react';\nimport { Icon } from './icon.mjs';\nimport { forwardRef } from '../system/forward-ref.mjs';\n\nfunction createIcon(options) {\n  const {\n    viewBox = \"0 0 24 24\",\n    d: pathDefinition,\n    displayName,\n    defaultProps = {}\n  } = options;\n  const path = Children.toArray(options.path);\n  const Comp = forwardRef((props, ref) => /* @__PURE__ */ jsx(Icon, { ref, viewBox, ...defaultProps, ...props, children: path.length ? path : /* @__PURE__ */ jsx(\"path\", { fill: \"currentColor\", d: pathDefinition }) }));\n  Comp.displayName = displayName;\n  return Comp;\n}\n\nexport { createIcon };\n","import { createIcon } from '@chakra-ui/react';\n\nconst CheckCircleIcon = createIcon({\n  displayName: \"CheckCircleIcon\",\n  d: \"M12,0A12,12,0,1,0,24,12,12.014,12.014,0,0,0,12,0Zm6.927,8.2-6.845,9.289a1.011,1.011,0,0,1-1.43.188L5.764,13.769a1,1,0,1,1,1.25-1.562l4.076,3.261,6.227-8.451A1,1,0,1,1,18.927,8.2Z\"\n});\n\nexport { CheckCircleIcon };\n","import { createIcon } from '@chakra-ui/react';\n\nconst WarningIcon = createIcon({\n  d: \"M11.983,0a12.206,12.206,0,0,0-8.51,3.653A11.8,11.8,0,0,0,0,12.207,11.779,11.779,0,0,0,11.8,24h.214A12.111,12.111,0,0,0,24,11.791h0A11.766,11.766,0,0,0,11.983,0ZM10.5,16.542a1.476,1.476,0,0,1,1.449-1.53h.027a1.527,1.527,0,0,1,1.523,1.47,1.475,1.475,0,0,1-1.449,1.53h-.027A1.529,1.529,0,0,1,10.5,16.542ZM11,12.5v-6a1,1,0,0,1,2,0v6a1,1,0,1,1-2,0Z\",\n  displayName: \"WarningIcon\"\n});\n\nexport { WarningIcon };\n","import React, { useState, useEffect } from 'react';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { auth } from '../services/api'; // Assuming auth service is still used\r\n\r\n// Import Chakra UI Components\r\nimport {\r\n  Box,\r\n  Flex,\r\n  Heading,\r\n  Text,\r\n  FormControl,\r\n  FormLabel,\r\n  Input,\r\n  Button,\r\n  VStack,\r\n  HStack,\r\n  useToast,\r\n  useColorModeValue,\r\n  Spinner,\r\n  Divider,\r\n  Switch,\r\n  AlertDialog,\r\n  AlertDialogBody,\r\n  AlertDialogFooter,\r\n  AlertDialogHeader,\r\n  AlertDialogContent,\r\n  AlertDialogOverlay,\r\n  useDisclosure,\r\n  FormErrorMessage,\r\n  Icon,\r\n} from '@chakra-ui/react';\r\nimport { CheckCircleIcon, WarningIcon } from '@chakra-ui/icons';\r\n\r\n// Import icons - Added FaArrowLeft import here\r\nimport { FaArrowLeft } from 'react-icons/fa';\r\n\r\n\r\nfunction SettingsPage() {\r\n  const navigate = useNavigate();\r\n  const toast = useToast();\r\n\r\n  // State for Account Settings (Change Password)\r\n  const [oldPassword, setOldPassword] = useState('');\r\n  const [newPassword, setNewPassword] = useState('');\r\n  const [confirmNewPassword, setConfirmNewPassword] = useState('');\r\n  const [passwordChangeLoading, setPasswordChangeLoading] = useState(false);\r\n  const [passwordErrors, setPasswordErrors] = useState({});\r\n  const [passwordChangeStatus, setPasswordChangeStatus] = useState(null);\r\n\r\n  // State for Preferences\r\n  const [receiveSms, setReceiveSms] = useState(true); // Default notification preference\r\n  const [receiveEmail, setReceiveEmail] = useState(true); // Default notification preference\r\n  const [preferencesSaving, setPreferencesSaving] = useState(false);\r\n  const [preferencesStatus, setPreferencesStatus] = useState(null);\r\n\r\n\r\n  // State and hooks for Delete Account Modal\r\n  const { isOpen, onOpen, onClose } = useDisclosure();\r\n  const cancelRef = React.useRef(); // Ref for the cancel button\r\n\r\n\r\n  const user = auth.getCurrentUser(); // Get current user data\r\n\r\n  // Chakra UI hook for dynamic colors based on color mode - Defined at the top level\r\n  const bgColor = useColorModeValue('gray.50', 'gray.800');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const mutedTextColor = useColorModeValue('gray.600', 'gray.400');\r\n  const spinnerColor = useColorModeValue('blue.500', 'blue.300');\r\n  const borderColor = useColorModeValue('gray.200', 'gray.600'); // Added border color\r\n  // Added glassmorphism border color definition\r\n  const glassBorderColor = useColorModeValue('rgba(255, 255, 255, 0.2)', 'rgba(255, 255, 255, 0.1)');\r\n  const glassBgColor = useColorModeValue('rgba(255, 255, 255, 0.15)', 'rgba(26, 32, 44, 0.15)');\r\n  const glassBoxShadow = useColorModeValue('0 4px 6px rgba(0, 0, 0, 0.1)', '0 4px 6px rgba(0, 0, 0, 0.4)');\r\n\r\n  // Define colors for conditionally rendered elements and input focus borders at the top level\r\n  const inputFocusBorderColor = useColorModeValue('blue.500', 'blue.300'); // For all inputs\r\n  const successIconColor = useColorModeValue('green.500', 'green.500'); // Assuming green is consistent\r\n  const warningIconColor = useColorModeValue('red.500', 'red.500'); // Assuming red is consistent\r\n  const successTextColor = useColorModeValue('green.500', 'green.500'); // Assuming green is consistent\r\n  const warningTextColor = useColorModeValue('red.500', 'red.500'); // Assuming red is consistent\r\n\r\n\r\n  // Redirect if user is not logged in\r\n  useEffect(() => {\r\n      if (!user) {\r\n          navigate('/login');\r\n          toast({\r\n               title: 'Authentication Required',\r\n               description: 'You need to be logged in to access this page.',\r\n               status: 'warning',\r\n               duration: 3000,\r\n               isClosable: true,\r\n          });\r\n      }\r\n  }, [user, navigate, toast]);\r\n\r\n  // Helper to format last login date (if user object includes it)\r\n  const formatLastLogin = (dateString) => {\r\n      if (!dateString) return 'N/A';\r\n      try {\r\n          const date = new Date(dateString);\r\n          return date.toLocaleString();\r\n      } catch (error) {\r\n          console.error(\"Error formatting date:\", error);\r\n          return dateString;\r\n      }\r\n  };\r\n\r\n\r\n  // Handle Password Change Submission (Mock API call)\r\n  const handleChangePassword = async (e) => {\r\n      e.preventDefault();\r\n      setPasswordErrors({}); // Clear previous errors\r\n      setPasswordChangeStatus(null); // Clear previous status\r\n\r\n      // Basic validation\r\n      const errors = {};\r\n      if (!oldPassword) errors.oldPassword = 'Old password is required';\r\n      if (!newPassword) {\r\n           errors.newPassword = 'New password is required';\r\n      } else if (newPassword.length < 6) {\r\n          errors.newPassword = 'New password must be at least 6 characters long';\r\n      }\r\n      if (!confirmNewPassword) {\r\n          errors.confirmNewPassword = 'Confirm new password is required';\r\n      } else if (newPassword !== confirmNewPassword) {\r\n          errors.confirmNewPassword = 'Passwords do not match';\r\n      }\r\n\r\n      if (Object.keys(errors).length > 0) {\r\n          setPasswordErrors(errors);\r\n           setPasswordChangeStatus({ status: 'error', message: 'Please fix the errors above' });\r\n          return;\r\n      }\r\n\r\n\r\n      setPasswordChangeLoading(true);\r\n\r\n      try {\r\n          // --- MOCK API CALL FOR CHANGE PASSWORD ---\r\n          console.log('Attempting to change password:', { oldPassword, newPassword });\r\n          await new Promise(resolve => setTimeout(resolve, 1500)); // Simulate API delay\r\n\r\n          // Simulate success or failure\r\n          const success = true; // Change to false to test error\r\n\r\n          if (success) {\r\n              toast({\r\n                  title: 'Password Updated',\r\n                  description: 'Your password has been updated successfully.',\r\n                  status: 'success',\r\n                  duration: 3000,\r\n                  isClosable: true,\r\n              });\r\n              // Clear form fields on success\r\n              setOldPassword('');\r\n              setNewPassword('');\r\n              setConfirmNewPassword('');\r\n              setPasswordChangeStatus({ status: 'success', message: 'Password updated successfully' });\r\n          } else {\r\n               toast({\r\n                  title: 'Password Change Failed',\r\n                  description: 'There was an error changing your password. Please try again later.',\r\n                  status: 'error',\r\n                  duration: 3000,\r\n                  isClosable: true,\r\n              });\r\n              setPasswordChangeStatus({ status: 'error', message: 'Password change failed' });\r\n          }\r\n\r\n      } catch (error) {\r\n          console.error('Password change error:', error);\r\n           toast({\r\n              title: 'Error Occurred',\r\n              description: error.message || 'Could not change password',\r\n              status: 'error',\r\n              duration: 5000,\r\n              isClosable: true,\r\n          });\r\n          setPasswordChangeStatus({ status: 'error', message: 'An error occurred' });\r\n      } finally {\r\n          setPasswordChangeLoading(false);\r\n           // Hide status message after a few seconds\r\n           setTimeout(() => setPasswordChangeStatus(null), 5000);\r\n      }\r\n  };\r\n\r\n  // Handle Preferences Save (Mock API call)\r\n   const handleSavePreferences = async () => {\r\n       setPreferencesSaving(true);\r\n       setPreferencesStatus(null); // Clear previous status\r\n       try {\r\n           // --- MOCK API CALL FOR SAVING PREFERENCES ---\r\n           console.log('Saving preferences:', { receiveSms, receiveEmail });\r\n\r\n           await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate API delay\r\n\r\n           toast({\r\n               title: 'Preferences Saved',\r\n               description: 'Your preferences have been saved successfully.',\r\n               status: 'success',\r\n               duration: 3000,\r\n               isClosable: true,\r\n           });\r\n            setPreferencesStatus({ status: 'success', message: 'Preferences saved successfully' });\r\n\r\n       } catch (error) {\r\n           console.error('Preferences save error:', error);\r\n            toast({\r\n               title: 'Error Occurred',\r\n               description: error.message || 'Could not save preferences',\r\n               status: 'error',\r\n               duration: 5000,\r\n               isClosable: true,\r\n           });\r\n            setPreferencesStatus({ status: 'error', message: 'Failed to save preferences' });\r\n       } finally {\r\n           setPreferencesSaving(false);\r\n           // Hide status message after a few seconds\r\n           setTimeout(() => setPreferencesStatus(null), 5000);\r\n       }\r\n   };\r\n\r\n\r\n  // Handle Delete Account\r\n  const handleDeleteAccount = async () => {\r\n      // --- MOCK DELETE ACCOUNT PROCESS ---\r\n      console.log('Deleting account for user:', user?.email);\r\n      // In a real app: Call delete API, then clear auth token and redirect\r\n\r\n      onClose(); // Close the confirmation modal\r\n      await new Promise(resolve => setTimeout(resolve, 1000)); // Simulate API delay\r\n\r\n      auth.logout(); // Clear auth token (assuming this clears localStorage)\r\n       toast({\r\n           title: 'Account Deleted',\r\n           description: 'Your account has been deleted successfully.',\r\n           status: 'success',\r\n           duration: 3000,\r\n           isClosable: true,\r\n       });\r\n      navigate('/login'); // Redirect to login page\r\n      // --- END MOCK PROCESS ---\r\n  };\r\n\r\n\r\n  // Render loading spinner while user is being checked or data is loading initially\r\n  if (!user) {\r\n       return (\r\n           <Flex minH=\"100vh\" align=\"center\" justify=\"center\" bg={bgColor}>\r\n               <Spinner size=\"xl\" color={spinnerColor} />\r\n           </Flex>\r\n       );\r\n   }\r\n\r\n  return (\r\n    // Applied background gradient and overlay to the outermost Box\r\n    <Box\r\n      minH=\"100vh\" // Ensure this Box takes the full viewport height\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\" // Gradient matching login page\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\" // Fixed background\r\n      position=\"relative\" // Needed for absolute positioning of overlay\r\n      _before={{ // Add an overlay for readability\r\n          content: '\"\"',\r\n          position: 'absolute',\r\n          top: 0,\r\n          left: 0,\r\n          right: 0,\r\n          bottom: 0,\r\n          bg: 'rgba(0, 0, 0, 0.5)', // Dark overlay with 50% opacity (adjust as needed)\r\n          zIndex: 1, // Ensure this is lower than the content Box's zIndex\r\n      }}\r\n    >\r\n        {/* Content Box with glassmorphism */}\r\n        <Box\r\n            maxW=\"container.lg\"\r\n            mx=\"auto\"\r\n            p={{ base: 4, md: 6 }}\r\n            position=\"relative\"\r\n            zIndex={2} // Ensure content is above the overlay\r\n            bg={glassBgColor} // Glassmorphism background\r\n            borderRadius=\"lg\" // Rounded corners for glassmorphism box\r\n            backdropFilter=\"blur(10px)\" // Apply blur effect for glassmorphism\r\n            borderWidth=\"1px\" // Optional: Add a subtle border\r\n            borderColor={glassBorderColor} // Use the defined glassmorphism border color\r\n            boxShadow={glassBoxShadow} // Optional: Add shadow\r\n            mt={8} // Add some margin top to separate from the top edge if needed\r\n            mb={8} // Add some margin bottom\r\n        >\r\n            {/* Header with Back to Dashboard Button */}\r\n            <HStack justify=\"space-between\" align=\"center\" mb={8}>\r\n                {/* Using the imported FaArrowLeft icon */}\r\n                <Button leftIcon={<FaArrowLeft />} variant=\"ghost\" onClick={() => navigate('/home')} color={headingColor}>\r\n                    Back to Home\r\n                </Button>\r\n                {/* You can add other header elements here if needed */}\r\n            </HStack>\r\n\r\n            <Heading as=\"h1\" size=\"xl\" color={headingColor} mb={8}>\r\n                Account Settings\r\n            </Heading>\r\n\r\n            <VStack spacing={8} align=\"stretch\">\r\n\r\n                {/* General Information Section */}\r\n                <Box>\r\n                    <Heading as=\"h2\" size=\"lg\" mb={4} color={headingColor}>General Information</Heading>\r\n                    <Text color={mutedTextColor} mb={4}>Review and update your profile details.</Text>\r\n                    <VStack spacing={4} align=\"stretch\">\r\n                        <FormControl id=\"email\">\r\n                            <FormLabel color={mutedTextColor}>Email Address</FormLabel>\r\n                            {/* Using the defined inputFocusBorderColor */}\r\n                            <Input type=\"email\" value={user?.email} isReadOnly focusBorderColor={inputFocusBorderColor} /> {/* Email is usually not changeable here */}\r\n                        </FormControl>\r\n                        {/* Display last login if available */}\r\n                         {user?.lastLogin && (\r\n                            <Box>\r\n                                <Text fontSize=\"sm\" color={mutedTextColor}>Last Login: {formatLastLogin(user.lastLogin)}</Text>\r\n                            </Box>\r\n                         )}\r\n                        {/* You can add more general user info fields here if your user object has them */}\r\n                    </VStack>\r\n                </Box>\r\n\r\n                <Divider borderColor={borderColor} /> {/* Add a divider */}\r\n\r\n                {/* Change Password Section */}\r\n                <Box>\r\n                    <Heading as=\"h2\" size=\"lg\" mb={4} color={headingColor}>Change Password</Heading>\r\n                    <Text color={mutedTextColor} mb={4}>Update your account password.</Text>\r\n                    <VStack spacing={4} as=\"form\" onSubmit={handleChangePassword}>\r\n                         <FormControl id=\"old-password\" isInvalid={passwordErrors.oldPassword}>\r\n                              <FormLabel color={mutedTextColor}>Old Password</FormLabel>\r\n                               {/* Using the defined inputFocusBorderColor */}\r\n                       <Input\r\n                         type=\"password\"\r\n                         value={oldPassword}\r\n                         onChange={(e) => setOldPassword(e.target.value)}\r\n                                   focusBorderColor={inputFocusBorderColor}\r\n                       />\r\n                       <FormErrorMessage>{passwordErrors.oldPassword}</FormErrorMessage>\r\n                     </FormControl>\r\n                         <FormControl id=\"new-password\" isInvalid={passwordErrors.newPassword}>\r\n                              <FormLabel color={mutedTextColor}>New Password</FormLabel>\r\n                               {/* Using the defined inputFocusBorderColor */}\r\n                       <Input\r\n                         type=\"password\"\r\n                         value={newPassword}\r\n                         onChange={(e) => setNewPassword(e.target.value)}\r\n                                   focusBorderColor={inputFocusBorderColor}\r\n                       />\r\n                       <FormErrorMessage>{passwordErrors.newPassword}</FormErrorMessage>\r\n                     </FormControl>\r\n                         <FormControl id=\"confirm-new-password\" isInvalid={passwordErrors.confirmNewPassword}>\r\n                              <FormLabel color={mutedTextColor}>Confirm New Password</FormLabel>\r\n                               {/* Using the defined inputFocusBorderColor */}\r\n                       <Input\r\n                         type=\"password\"\r\n                         value={confirmNewPassword}\r\n                         onChange={(e) => setConfirmNewPassword(e.target.value)}\r\n                                   focusBorderColor={inputFocusBorderColor}\r\n                       />\r\n                       <FormErrorMessage>{passwordErrors.confirmNewPassword}</FormErrorMessage>\r\n                     </FormControl>\r\n                         <Button type=\"submit\" colorScheme=\"blue\" isLoading={passwordChangeLoading}>\r\n                       Change Password\r\n                     </Button>\r\n                         {passwordChangeStatus && (\r\n                             <HStack>\r\n                                  {/* Using the defined successIconColor and warningIconColor */}\r\n                                  <Icon\r\n                                      as={passwordChangeStatus.status === 'success' ? CheckCircleIcon : WarningIcon}\r\n                                       color={passwordChangeStatus.status === 'success' ? successIconColor : warningIconColor}\r\n                                  />\r\n                                   {/* Using the defined successTextColor and warningTextColor */}\r\n                                  <Text color={passwordChangeStatus.status === 'success' ? successTextColor : warningTextColor} fontSize=\"sm\">\r\n                                      {passwordChangeStatus.message}\r\n                                  </Text>\r\n                             </HStack>\r\n                         )}\r\n                </VStack>\r\n            </Box>\r\n\r\n                 <Divider borderColor={borderColor} /> {/* Add another divider */}\r\n\r\n                 {/* Notification Preferences Section */}\r\n                 <Box>\r\n                     <Heading as=\"h2\" size=\"lg\" mb={4} color={headingColor}>Notification Preferences</Heading>\r\n                     <Text color={mutedTextColor} mb={4}>Choose how you want to receive notifications.</Text>\r\n                     <VStack spacing={4} align=\"stretch\">\r\n                         <HStack justify=\"space-between\">\r\n                             <FormLabel htmlFor=\"receive-sms\" mb=\"0\" color={mutedTextColor}>\r\n                                 Receive SMS Notifications\r\n                             </FormLabel>\r\n                             <Switch id=\"receive-sms\" isChecked={receiveSms} onChange={(e) => setReceiveSms(e.target.checked)} colorScheme=\"blue\" />\r\n                         </HStack>\r\n                         <HStack justify=\"space-between\">\r\n                             <FormLabel htmlFor=\"receive-email\" mb=\"0\" color={mutedTextColor}>\r\n                                 Receive Email Notifications\r\n                             </FormLabel>\r\n                             <Switch id=\"receive-email\" isChecked={receiveEmail} onChange={(e) => setReceiveEmail(e.target.checked)} colorScheme=\"blue\" />\r\n                         </HStack>\r\n                         <Button onClick={handleSavePreferences} isLoading={preferencesSaving} colorScheme=\"blue\" alignSelf=\"flex-start\">\r\n                             Save Preferences\r\n                         </Button>\r\n                     {preferencesStatus && (\r\n                              <HStack>\r\n                                   {/* Using the defined successIconColor and warningIconColor */}\r\n                            <Icon\r\n                                as={preferencesStatus.status === 'success' ? CheckCircleIcon : WarningIcon}\r\n                                       color={preferencesStatus.status === 'success' ? successIconColor : warningIconColor}\r\n                                  />\r\n                                   {/* Using the defined successTextColor and warningTextColor */}\r\n                                  <Text color={preferencesStatus.status === 'success' ? successTextColor : warningTextColor} fontSize=\"sm\">\r\n                                      {preferencesStatus.message}\r\n                                  </Text>\r\n                              </HStack>\r\n                          )}\r\n                </VStack>\r\n            </Box>\r\n\r\n\r\n                <Divider borderColor={borderColor} /> {/* Add another divider */}\r\n\r\n                {/* Delete Account Section */}\r\n                <Box>\r\n                    <Heading as=\"h2\" size=\"lg\" mb={4} color={headingColor}>Danger Zone</Heading>\r\n                    <Text color=\"red.400\" mb={4}>Deleting your account is irreversible.</Text>\r\n                    <Button colorScheme=\"red\" onClick={onOpen}>\r\n                        Delete Account\r\n                 </Button>\r\n\r\n            {/* Delete Account Confirmation Modal */}\r\n             <AlertDialog\r\n                isOpen={isOpen}\r\n                leastDestructiveRef={cancelRef}\r\n                onClose={onClose}\r\n             >\r\n                <AlertDialogOverlay>\r\n                <AlertDialogContent>\r\n                    <AlertDialogHeader fontSize=\"lg\" fontWeight=\"bold\">\r\n                                    Delete Account\r\n                    </AlertDialogHeader>\r\n\r\n                    <AlertDialogBody>\r\n                    Are you sure you want to delete your account? This action cannot be undone.\r\n                    </AlertDialogBody>\r\n\r\n                    <AlertDialogFooter>\r\n                    <Button ref={cancelRef} onClick={onClose}>\r\n                        Cancel\r\n                    </Button>\r\n                    <Button colorScheme=\"red\" onClick={handleDeleteAccount} ml={3}>\r\n                        Delete\r\n                    </Button>\r\n                    </AlertDialogFooter>\r\n                </AlertDialogContent>\r\n                </AlertDialogOverlay>\r\n             </AlertDialog>\r\n                </Box>\r\n\r\n            </VStack>\r\n        </Box>\r\n    </Box>\r\n  );\r\n}\r\n\r\nexport default SettingsPage;","'use client';\nimport { jsx } from 'react/jsx-runtime';\nimport { omitThemingProps } from '@chakra-ui/styled-system';\nimport { createContext, cx } from '@chakra-ui/utils';\nimport { forwardRef } from '../system/forward-ref.mjs';\nimport { useMultiStyleConfig } from '../system/use-style-config.mjs';\nimport { chakra } from '../system/factory.mjs';\n\nconst [StatStylesProvider, useStatStyles] = createContext({\n  name: `StatStylesContext`,\n  errorMessage: `useStatStyles returned is 'undefined'. Seems you forgot to wrap the components in \"<Stat />\" `\n});\nconst Stat = forwardRef(function Stat2(props, ref) {\n  const styles = useMultiStyleConfig(\"Stat\", props);\n  const sta