hu', 'Fri', 'Sat'];\r\n\r\nconst EventCalendar = () => {\r\n  const toast = useToast();\r\n  const today = new Date();\r\n  const [currentMonth, setCurrentMonth] = useState(today.getMonth());\r\n  const [currentYear, setCurrentYear] = useState(today.getFullYear());\r\n  const [selectedDate, setSelectedDate] = useState(null);\r\n  const [events, setEvents] = useState({});\r\n  const { isOpen, onOpen, onClose } = useDisclosure();\r\n  const { isOpen: isDeleteOpen, onOpen: onDeleteOpen, onClose: onDeleteClose } = useDisclosure();\r\n  const [eventData, setEventData] = useState({\r\n    title: '',\r\n    start: '',\r\n    end: '',\r\n    description: '',\r\n    location: '',\r\n    eventType: 'meeting'\r\n  });\r\n  const [deleteConfirmationText, setDeleteConfirmationText] = useState('');\r\n\r\n  // Move color mode values to top level\r\n  const dateBg = useColorModeValue('gray.100', 'gray.700');\r\n  const dateColor = useColorModeValue('gray.700', 'gray.200');\r\n  const monthColor = useColorModeValue('gray.800', 'whiteAlpha.900');\r\n  const dayColor = useColorModeValue('gray.600', 'gray.300');\r\n  const calendarBg = useColorModeValue('white', 'gray.800');\r\n\r\n  // Create color mode values for event types at top level\r\n  const eventTypeColors = {\r\n    meeting: useColorModeValue('blue.500', 'blue.300'),\r\n    maintenance: useColorModeValue('orange.500', 'orange.300'),\r\n    appointment: useColorModeValue('green.500', 'green.300'),\r\n    reminder: useColorModeValue('purple.500', 'purple.300'),\r\n    other: useColorModeValue('gray.500', 'gray.300')\r\n  };\r\n\r\n  // Add state for hover tracking\r\n  const [hoveredDay, setHoveredDay] = useState(null);\r\n\r\n  // Add color mode values at the top with other style configs\r\n  const hoverCardBg = useColorModeValue('white', 'gray.700');\r\n  const hoverCardText = useColorModeValue('gray.800', 'whiteAlpha.900');\r\n\r\n  // Add new state for search\r\n  const [searchQuery, setSearchQuery] = useState('');\r\n  const [debouncedSearchQuery, setDebouncedSearchQuery] = useState('');\r\n\r\n  // Add new state for filters\r\n  const [activeFilters, setActiveFilters] = useState([]);\r\n\r\n  // Add filter toggle function\r\n  const toggleFilter = (eventType) => {\r\n    setActiveFilters(prev => \r\n      prev.includes(eventType)\r\n        ? prev.filter(f => f !== eventType)\r\n        : [...prev, eventType]\r\n    );\r\n  };\r\n\r\n  // Add debounce effect\r\n  useEffect(() => {\r\n    const handler = setTimeout(() => {\r\n      setDebouncedSearchQuery(searchQuery.toLowerCase());\r\n    }, 300);\r\n\r\n    return () => {\r\n      clearTimeout(handler);\r\n    };\r\n  }, [searchQuery]);\r\n\r\n  const getDaysInMonth = (month, year) => new Date(year, month + 1, 0).getDate();\r\n\r\n  const startDay = new Date(currentYear, currentMonth, 1).getDay();\r\n  const daysInMonth = getDaysInMonth(currentMonth, currentYear);\r\n\r\n  useEffect(() => {\r\n    const savedEvents = localStorage.getItem('calendarEvents');\r\n    if (savedEvents) {\r\n      setEvents(JSON.parse(savedEvents));\r\n    }\r\n  }, []);\r\n\r\n  const handlePrev = () => {\r\n    if (currentMonth === 0) {\r\n      setCurrentMonth(11);\r\n      setCurrentYear(currentYear - 1);\r\n    } else {\r\n      setCurrentMonth(currentMonth - 1);\r\n    }\r\n  };\r\n\r\n  const handleNext = () => {\r\n    if (currentMonth === 11) {\r\n      setCurrentMonth(0);\r\n      setCurrentYear(currentYear + 1);\r\n    } else {\r\n      setCurrentMonth(currentMonth + 1);\r\n    }\r\n  };\r\n\r\n  const handleDateClick = (day) => {\r\n    const key = `${currentYear}-${currentMonth}-${day}`;\r\n    setSelectedDate(key);\r\n    setEventData(events[key] || {\r\n      title: '',\r\n      start: '',\r\n      end: '',\r\n      description: '',\r\n      location: '',\r\n      eventType: 'meeting'\r\n    });\r\n    onOpen();\r\n  };\r\n\r\n  const saveEvent = () => {\r\n    // Validate all required fields\r\n    if (!eventData.title.trim() || \r\n        !eventData.start || \r\n        !eventData.end || \r\n        !eventData.description.trim() || \r\n        !eventData.location.trim()) {\r\n      toast({\r\n        title: 'Missing required fields',\r\n        description: 'Please fill in all event details',\r\n        status: 'error',\r\n        duration: 3000,\r\n        isClosable: true,\r\n        position: 'bottom',\r\n      });\r\n      return;\r\n    }\r\n\r\n    const updated = { \r\n      ...events, \r\n      [selectedDate]: eventData \r\n    };\r\n    setEvents(updated);\r\n    localStorage.setItem('calendarEvents', JSON.stringify(updated));\r\n    onClose();\r\n    \r\n    toast({\r\n      title: 'Event created',\r\n      description: 'Your event has been successfully saved',\r\n      status: 'success',\r\n      duration: 3000,\r\n      isClosable: true,\r\n      position: 'bottom',\r\n    });\r\n  };\r\n\r\n  // Add ref for tracking deleted event\r\n  const deletedEventRef = useRef(null);\r\n\r\n  // Modify deleteEvent function\r\n  const deleteEvent = () => {\r\n    if (deleteConfirmationText.toLowerCase() !== 'delete') return;\r\n\r\n    // Store deleted event before removal\r\n    deletedEventRef.current = {\r\n      key: selectedDate,\r\n      event: events[selectedDate]\r\n    };\r\n\r\n    const updated = { ...events };\r\n    delete updated[selectedDate];\r\n    setEvents(updated);\r\n    localStorage.setItem('calendarEvents', JSON.stringify(updated));\r\n    \r\n    setDeleteConfirmationText('');\r\n    onDeleteClose();\r\n    onClose();\r\n    \r\n    toast({\r\n      title: 'Event deleted',\r\n      description: 'Click Undo to restore it',\r\n      status: 'success',\r\n      duration: 5000,\r\n      isClosable: true,\r\n      position: 'bottom',\r\n      onCloseComplete: () => {\r\n        // Clear the ref when toast closes\r\n        deletedEventRef.current = null;\r\n      },\r\n      render: ({ onClose }) => (\r\n        <Box\r\n          color=\"white\"\r\n          p={3}\r\n          bg=\"blue.500\"\r\n          borderRadius=\"md\"\r\n          display=\"flex\"\r\n          alignItems=\"center\"\r\n          justifyContent=\"space-between\"\r\n        >\r\n          <Text>Event deleted. Click Undo to restore it</Text>\r\n          <Button\r\n            size=\"sm\"\r\n            colorScheme=\"blue\"\r\n            variant=\"ghost\"\r\n            onClick={() => {\r\n              if (deletedEventRef.current) {\r\n                const { key, event } = deletedEventRef.current;\r\n                setEvents(prev => ({\r\n                  ...prev,\r\n                  [key]: event\r\n                }));\r\n                localStorage.setItem('calendarEvents', \r\n                  JSON.stringify({\r\n                    ...events,\r\n                    [key]: event\r\n                  })\r\n                );\r\n                deletedEventRef.current = null;\r\n                onClose();\r\n              }\r\n            }}\r\n          >\r\n            Undo\r\n          </Button>\r\n        </Box>\r\n      )\r\n    });\r\n  };\r\n\r\n  const renderCalendar = (dateBg, dateColor) => {\r\n    const totalCells = startDay + daysInMonth;\r\n    const weeks = [];\r\n    let dayCounter = 1;\r\n\r\n    for (let i = 0; i < totalCells; i++) {\r\n      const isEmpty = i < startDay;\r\n      const key = `${currentYear}-${currentMonth}-${dayCounter}`;\r\n      const event = events[key];\r\n      const isEvent = event && \r\n        event.title.toLowerCase().includes(debouncedSearchQuery) &&\r\n        (activeFilters.length === 0 || activeFilters.includes(event.eventType));\r\n      \r\n      if (!isEmpty) {\r\n        const currentDay = dayCounter;\r\n        weeks.push(\r\n          <Box\r\n            key={i}\r\n            w=\"40px\"\r\n            h=\"40px\"\r\n            m=\"1\"\r\n            borderRadius=\"md\"\r\n            border=\"1px solid\"\r\n            borderColor=\"gray.200\"\r\n            boxShadow=\"sm\"\r\n            transition=\"0.2s\"\r\n            bg={isEvent ? eventTypeColors[event.eventType] : dateBg}\r\n            color={isEvent ? 'white' : dateColor}\r\n            display=\"flex\"\r\n            alignItems=\"center\"\r\n            justifyContent=\"center\"\r\n            cursor=\"pointer\"\r\n            onClick={() => handleDateClick(currentDay)}\r\n            onMouseEnter={() => isEvent && setHoveredDay(key)}\r\n            onMouseLeave={() => setHoveredDay(null)}\r\n            position=\"relative\"\r\n            _hover={{\r\n              transform: 'scale(1.05)',\r\n              boxShadow: 'md'\r\n            }}\r\n          >\r\n            {currentDay}\r\n            {isEvent && (\r\n              <>\r\n                <Box \r\n                  position=\"absolute\" \r\n                  bottom=\"1\" \r\n                  right=\"1\" \r\n                  bg=\"red.400\" \r\n                  w=\"2\" \r\n                  h=\"2\" \r\n                  borderRadius=\"full\"\r\n                />\r\n                {hoveredDay === key && (\r\n                  <Box\r\n                    position=\"absolute\"\r\n                    bottom=\"100%\"\r\n                    left=\"50%\"\r\n                    transform=\"translateX(-50%)\"\r\n                    bg={hoverCardBg}\r\n                    p={2}\r\n                    boxShadow=\"xl\"\r\n                    borderRadius=\"md\"\r\n                    fontSize=\"xs\"\r\n                    zIndex=\"tooltip\"\r\n                    minWidth=\"120px\"\r\n                    borderWidth=\"1px\"\r\n                    borderColor=\"gray.200\"\r\n                  >\r\n                    <Text fontWeight=\"bold\" color={hoverCardText}>\r\n                      {event.title}\r\n                    </Text>\r\n                    <Text color={hoverCardText}>\r\n                      {new Date(event.start).toLocaleTimeString([], { \r\n                        hour: '2-digit', \r\n                        minute: '2-digit' \r\n                      })}\r\n                    </Text>\r\n                    <Text color={hoverCardText} textTransform=\"capitalize\">\r\n                      {event.eventType}\r\n                    </Text>\r\n                  </Box>\r\n                )}\r\n              </>\r\n            )}\r\n          </Box>\r\n        );\r\n        dayCounter++;\r\n      } else {\r\n        weeks.push(\r\n          <Box key={i} w=\"40px\" h=\"40px\" m=\"1\" />\r\n        );\r\n      }\r\n    }\r\n\r\n    return weeks;\r\n  };\r\n\r\n  return (\r\n    <Box \r\n      bg={calendarBg}\r\n      p={8}\r\n      rounded=\"lg\" \r\n      shadow=\"lg\" \r\n      maxW=\"700px\"\r\n      mx=\"auto\"\r\n      color={monthColor}\r\n      position=\"relative\"\r\n    >\r\n      <Flex justify=\"space-between\" align=\"center\" mb={4}>\r\n        <IconButton\r\n          icon={<ChevronLeftIcon />}\r\n          onClick={handlePrev}\r\n          aria-label=\"Previous month\"\r\n          variant=\"ghost\"\r\n        />\r\n        <Text fontSize=\"xl\" fontWeight=\"bold\" color={monthColor}>\r\n          {new Date(currentYear, currentMonth).toLocaleString('default', {\r\n            month: 'long',\r\n            year: 'numeric',\r\n          })}\r\n        </Text>\r\n        <IconButton\r\n          icon={<ChevronRightIcon />}\r\n          onClick={handleNext}\r\n          aria-label=\"Next month\"\r\n          variant=\"ghost\"\r\n        />\r\n      </Flex>\r\n\r\n      {/* Add search input */}\r\n      <Input\r\n        placeholder=\"Search events...\"\r\n        value={searchQuery}\r\n        onChange={(e) => setSearchQuery(e.target.value)}\r\n        mb={4}\r\n        variant=\"filled\"\r\n        _focus={{ borderColor: 'blue.300' }}\r\n      />\r\n\r\n      {/* Add filter section */}\r\n      <Box mb={4}>\r\n        <Text fontSize=\"sm\" fontWeight=\"semibold\" mb={2} color={dayColor}>\r\n          Filter by event type\r\n        </Text>\r\n        <Flex wrap=\"wrap\" gap={2}>\r\n          {Object.keys(eventTypeColors).map((eventType) => (\r\n            <Button\r\n              key={eventType}\r\n              size=\"sm\"\r\n              variant={activeFilters.includes(eventType) ? 'solid' : 'outline'}\r\n              colorScheme={eventTypeColors[eventType].split('.')[0]}\r\n              onClick={() => toggleFilter(eventType)}\r\n              textTransform=\"capitalize\"\r\n            >\r\n              {eventType}\r\n            </Button>\r\n          ))}\r\n        </Flex>\r\n      </Box>\r\n\r\n      <Grid templateColumns=\"repeat(7, 1fr)\" gap={2} mb={2}>\r\n        {days.map((day) => (\r\n          <Text \r\n            key={day} \r\n            fontSize=\"sm\" \r\n            textAlign=\"center\" \r\n            fontWeight=\"bold\"\r\n            color={dayColor}\r\n          >\r\n            {day}\r\n          </Text>\r\n        ))}\r\n      </Grid>\r\n\r\n      <AnimatePresence mode='wait'>\r\n        <motion.div\r\n          key={`${currentYear}-${currentMonth}`}\r\n          initial={{ opacity: 0, y: 10 }}\r\n          animate={{ opacity: 1, y: 0 }}\r\n          exit={{ opacity: 0, y: -10 }}\r\n          transition={{ duration: 0.2 }}\r\n        >\r\n          <Grid templateColumns=\"repeat(7, 1fr)\">\r\n            {renderCalendar(dateBg, dateColor)}\r\n          </Grid>\r\n        </motion.div>\r\n      </AnimatePresence>\r\n\r\n      {/* Event Modal */}\r\n      <Modal isOpen={isOpen} onClose={onClose} isCentered>\r\n        <ModalOverlay />\r\n        <ModalContent>\r\n          <ModalHeader>Add Event</ModalHeader>\r\n          <ModalBody>\r\n            <Stack spacing={3}>\r\n              <Input\r\n                placeholder=\"Event Title *\"\r\n                value={eventData.title}\r\n                onChange={(e) => setEventData({...eventData, title: e.target.value})}\r\n                isRequired\r\n              />\r\n              <Input\r\n                type=\"datetime-local\"\r\n                value={eventData.start}\r\n                onChange={(e) => setEventData({...eventData, start: e.target.value})}\r\n                isRequired\r\n              />\r\n              <Input\r\n                type=\"datetime-local\"\r\n                placeholder=\"End Date/Time\"\r\n                value={eventData.end}\r\n                onChange={(e) => setEventData({...eventData, end: e.target.value})}\r\n                isRequired\r\n              />\r\n              <Textarea\r\n                placeholder=\"Description\"\r\n                value={eventData.description}\r\n                onChange={(e) => setEventData({...eventData, description: e.target.value})}\r\n                isRequired\r\n              />\r\n              <Input\r\n                placeholder=\"Location\"\r\n                value={eventData.location}\r\n                onChange={(e) => setEventData({...eventData, location: e.target.value})}\r\n                isRequired\r\n              />\r\n              <Select \r\n                value={eventData.eventType}\r\n                onChange={(e) => setEventData({...eventData, eventType: e.target.value})}\r\n                isRequired\r\n              >\r\n                <option value=\"meeting\">Meeting</option>\r\n                <option value=\"maintenance\">Maintenance</option>\r\n                <option value=\"appointment\">Appointment</option>\r\n                <option value=\"reminder\">Reminder</option>\r\n                <option value=\"other\">Other</option>\r\n              </Select>\r\n            </Stack>\r\n          </ModalBody>\r\n          <ModalFooter>\r\n            <Button variant=\"ghost\" mr={3} onClick={onClose}>\r\n              Cancel\r\n            </Button>\r\n            {events[selectedDate] && (\r\n              <Button \r\n                colorScheme=\"red\" \r\n                mr={3} \r\n                onClick={onDeleteOpen}\r\n              >\r\n                Delete\r\n              </Button>\r\n            )}\r\n            <Button colorScheme=\"blue\" onClick={saveEvent}>\r\n              {events[selectedDate] ? 'Update' : 'Save'}\r\n            </Button>\r\n          </ModalFooter>\r\n        </ModalContent>\r\n      </Modal>\r\n\r\n      {/* Confirmation Modal */}\r\n      <Modal isOpen={isDeleteOpen} onClose={onDeleteClose} isCentered>\r\n        <ModalOverlay />\r\n        <ModalContent>\r\n          <ModalHeader>Confirm Deletion</ModalHeader>\r\n          <ModalBody>\r\n            <Text mb={4}>\r\n              Type \"DELETE\" to confirm permanent removal of this event:\r\n            </Text>\r\n            <Input\r\n              value={deleteConfirmationText}\r\n              onChange={(e) => setDeleteConfirmationText(e.target.value)}\r\n              placeholder=\"Type DELETE here\"\r\n              autoFocus\r\n            />\r\n          </ModalBody>\r\n          <ModalFooter>\r\n            <Button variant=\"ghost\" mr={3} onClick={() => {\r\n              setDeleteConfirmationText('');\r\n              onDeleteClose();\r\n            }}>\r\n              Cancel\r\n            </Button>\r\n            <Button \r\n              colorScheme=\"red\" \r\n              onClick={deleteEvent}\r\n              isDisabled={deleteConfirmationText.toLowerCase() !== 'delete'}\r\n            >\r\n              Confirm Delete\r\n            </Button>\r\n          </ModalFooter>\r\n        </ModalContent>\r\n      </Modal>\r\n    </Box>\r\n  );\r\n};\r\n\r\nexport default EventCalendar;\r\n","import { createContext, useContext } from 'react';\nexport const CONTEXT_VERSION = 1;\nexport function createLeafletContext(map) {\n    return Object.freeze({\n        __version: CONTEXT_VERSION,\n        map\n    });\n}\nexport function extendContext(source, extra) {\n    return Object.freeze({\n        ...source,\n        ...extra\n    });\n}\nexport const LeafletContext = createContext(null);\nexport const LeafletProvider = LeafletContext.Provider;\nexport function useLeafletContext() {\n    c