    id: 2,\r\n      name: \"Nomsa Dlamini\",\r\n      date: \"2025-03-10\",\r\n      status: \"pending\",\r\n      reward: \"25 energy units\"\r\n    },\r\n    {\r\n      id: 3,\r\n      name: \"Sipho Nkosi\",\r\n      date: \"2025-03-05\",\r\n      status: \"completed\",\r\n      reward: \"50 energy units\"\r\n    }\r\n  ], []);\r\n\r\n  // Color mode values\r\n  const cardBg = useColorModeValue('white', 'gray.700');\r\n  const borderColor = useColorModeValue('gray.200', 'gray.600');\r\n  const textColor = useColorModeValue('gray.600', 'gray.400');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n\r\n  const handleCopyLink = () => {\r\n    navigator.clipboard.writeText(referralLink);\r\n    setCopied(true);\r\n    toast({\r\n      title: \"Link copied!\",\r\n      description: \"Your referral link has been copied to clipboard\",\r\n      status: \"success\",\r\n      duration: 2000,\r\n      isClosable: true,\r\n    });\r\n    setTimeout(() => setCopied(false), 2000);\r\n  };\r\n\r\n  const handleShare = (platform) => {\r\n    let shareUrl = '';\r\n    const shareText = \"Join me on this amazing energy platform! Use my referral link: \";\r\n\r\n    switch (platform) {\r\n      case 'whatsapp':\r\n        shareUrl = `https://wa.me/?text=${encodeURIComponent(shareText + referralLink)}`;\r\n        break;\r\n      case 'facebook':\r\n        shareUrl = `https://www.facebook.com/sharer/sharer.php?u=${encodeURIComponent(referralLink)}`;\r\n        break;\r\n      case 'email':\r\n        shareUrl = `mailto:?subject=Join me on Energy Platform&body=${encodeURIComponent(shareText + referralLink)}`;\r\n        break;\r\n      default:\r\n        return;\r\n    }\r\n\r\n    window.open(shareUrl, '_blank');\r\n  };\r\n\r\n  return (\r\n    <Box\r\n      minH=\"100vh\"\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\"\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\