shboard must be used within a DashboardProvider');\r\n  }\r\n  return context;\r\n};\r\n\r\nconst Dashboard = () => {\r\n  const { enabledWidgets } = useDashboard();\r\n  const navigate = useNavigate();\r\n\r\n  // Override with dark theme colors as per instructions\r\n  const backgroundColor = '#1e1e2f';  // Dark background\r\n  const cardBg = '#2b2b3d';  // Card backgrounds\r\n  const textColor = '#ffffff';  // Light text\r\n  const accentColor = 'teal.300';  // Accent for highlights\r\n\r\n  return (\r\n    <Box\r\n      minH=\"100vh\"\r\n      bg={backgroundColor}  // Apply dark background\r\n      color={textColor}  // Apply light text color\r\n      overflowY=\"auto\"\r\n      px={{ base: 4, md: 8 }}\r\n      py={6}\r\n    >\r\n      <Flex direction=\"row\" w=\"full\" maxW=\"1400px\" mx=\"auto\">\r\n        {/* Vertical Sidebar */}\r\n        <Box\r\n          as=\"nav\"\r\n          w={{ base: '60px', md: '200px' }}  // Collapse on small screens\r\n          bg=\"gray.800\"\r\n          h=\"100vh\"\r\n          position=\"fixed\"\r\n          left={0}\r\n          p={4}\r\n          borderRightWidth=\"1px\"\r\n          borderColor=\"gray.700\"\r\n        >\r\n          <Flex direction=\"column\" align=\"center\" gap={6}>\r\n            <Text fontSize=\"lg\" fontWeight=\"bold\">Menu</Text>\r\n            <Button variant=\"ghost\" onClick={() => navigate('/home')} leftIcon={<FaHome />} />\r\n            <Button variant=\"ghost\" onClick={() => navigate('/dashboard')} leftIcon={<FaTachometerAlt />} />\r\n            <Button variant=\"ghost\" onClick={() => navigate('/settings')} leftIcon={<FaCog />} />\r\n            <Button variant=\"ghost\" onClick={() => navigate('/logout')} leftIcon={<FaSignOutAlt />} />\r\n          </Flex>\r\n        </Box>\r\n\r\n        {/* Main Content with Padding for Sidebar */}\r\n        <Box ml={{ base: 0, md: '200px' }} w=\"full\" px={8} py={6}>\r\n          <Heading as=\"h1\" size=\"xl\" color={accentColor} mb={8}>\r\n            Energy Dashboard\r\n          </Heading>\r\n\r\n          {/* Widget Grid with Specified Grouping */}\r\n          <SimpleGrid\r\n            columns={{ base: 1, md: 2, lg: 3 }}\r\n            spacing={6}\r\n            mb={8}\r\n          >\r\n            {/* Top Row: Energy Mode, Daily Forecast, Energy Status */}\r\n            {enabledWidgets.includes('EnergyModeToggle') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <EnergyModeToggle />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n            {enabledWidgets.includes('DailyForecast') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <DailyForecast />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n            {enabledWidgets.includes('EnergyAvatar') && (  // Assuming EnergyAvatar is Energy Status\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <EnergyAvatar />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n\r\n            {/* Second Row: Monthly Budget, Solar Output, Theme Presets */}\r\n            {enabledWidgets.includes('BudgetDial') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <BudgetDial />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n            {enabledWidgets.includes('SolarOutput') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <SolarOutput />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n            {enabledWidgets.includes('ThemeSwitcher') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <ThemeSwitcher />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n\r\n            {/* Third Row: AI Tips, Activity Report, Widget Layout */}\r\n            {enabledWidgets.includes('AITipsPanel') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <AITipsPanel />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n            {enabledWidgets.includes('ActivityReport') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <ActivityReport />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n            {enabledWidgets.includes('WidgetLayout') && (\r\n              <ErrorBoundary>\r\n                <Box bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n                  <WidgetLayout />\r\n                </Box>\r\n              </ErrorBoundary>\r\n            )}\r\n          </SimpleGrid>\r\n\r\n          {/* Full-width Energy Usage Chart at the Bottom */}\r\n          <Box w=\"full\" mt={8} bg={cardBg} p={6} borderRadius=\"2xl\" boxShadow=\"md\" _hover={{ boxShadow: \"lg\" }}>\r\n            <ErrorBoundary>\r\n              <DashboardCard title=\"Energy Usage\" icon={FaBolt}>\r\n                <Box h=\"300px\">\r\n                  <ResponsiveContainer width=\"100%\" height=\"100%\">\r\n                    <LineChart\r\n                      data={[]}\r\n                      margin={{\r\n                        top: 5,\r\n                        right: 30,\r\n                        left: 20,\r\n                        bottom: 5,\r\n                      }}\r\n                    >\r\n                      <XAxis\r\n                        dataKey=\"name\"\r\n                        tickFormatter={(str) => {\r\n                          if (str === '2023-04-24') {\r\n                            return '24';\r\n                          }\r\n                          return '';\r\n                        }}\r\n                      />\r\n                      <YAxis />\r\n                      <Tooltip\r\n                        labelFormatter={(value) => {\r\n                          return `Usage: ${value} kWh`;\r\n                        }}\r\n                      />\r\n                      <Line type=\"monotone\" dataKey=\"usage\" stroke={accentColor} strokeWidth={2} />\r\n                    </LineChart>\r\n                  </ResponsiveContainer>\r\n                </Box>\r\n              </DashboardCard>\r\n            </ErrorBoundary>\r\n          </Box>\r\n        </Box>\r\n      </Flex>\r\n    </Box>\r\n  );\r\n};\r\n\r\nexport default Dashboard; ","import React, { createContext, useContext, useState, useEffect } from 'react';\r\n\r\nconst SubscriptionContext = createContext();\r\n\r\nexport function SubscriptionProvider({ children }) {\r\n  const [selectedPlan, setSelectedPlan] = useState(null);\r\n\r\n  useEffect(() => {\r\n    // Load from localStorage on mount\r\n    const storedPlan = localStorage.getItem('selectedPlan');\r\n    if (storedPlan) setSelectedPlan(JSON.parse(storedPlan));\r\n  }, []);\r\n\r\n  const selectPlan = (plan) => {\r\n    setSelectedPlan(plan);\r\n    localStorage.setItem('selectedPlan', JSON.stringify(plan));\r\n  };\r\n\r\n  return (\r\n    <SubscriptionContext.Provider value={{ selectedPlan, selectPlan }}>\r\n      {children}\r\n    </SubscriptionContext.Provider>\r\n  );\r\n}\r\n\r\nexport function useSubscription() {\r\n  return useContext(SubscriptionContext);\r\n}\r\n","'use client';\nimport { jsx } from 'react/jsx-runtime';\nimport { forwardRef } from '../system/forward-ref.mjs';\n\nconst NativeImage = forwardRef(function NativeImage2(props, ref) {\n  const { htmlWidth, htmlHeight, alt, ...rest } = props;\n  return /* @__PURE__ */ jsx(\"img\", { width: htmlWidth, height: htmlHeight, ref, alt, ...rest });\n});\nNativeImage.displayName = \"NativeImage\";\n\nexport { NativeImage };\n","'use client';\nimport { jsx } from 'react/jsx-runtime';\nimport { omit } from '@chakra-ui/utils';\nimport { NativeImage } from './native-image.mjs';\nimport { useImage, shouldShowFallbackImage } from './use-image.mjs';\nimport { forwardRef } from '../system/forward-ref.mjs';\nimport { chakra } from '../system/factory.mjs';\n\nconst Image = forwardRef(function Image2(props, ref) {\n  const {\n    fallbackSrc,\n    fallback,\n    src,\n    srcSet,\n    align,\n    fit,\n    loading,\n    ignoreFallback,\n    crossOrigin,\n    fallbackStrategy = \"beforeLoadOrError\",\n    referrerPolicy,\n    ...rest\n  } = props;\n  const providedFallback = fallbackSrc !== void 0 || fallback !== void 0;\n  const shouldIgnoreFallbackImage = loading != null || // use can opt out of fallback image\n  ignoreFallback || // if the user doesn't provide any kind of fallback we should ignore it\n  !providedFallback;\n  const status = useImage({\n    ...props,\n    crossOrigin,\n    ignoreFallback: shouldIgnoreFallbackImage\n  });\n  const showFallbackImage = shouldShowFallbackImage(status, fallbackStrategy);\n  const shared = {\n    ref,\n    objectFit: fit,\n    objectPosition: align,\n    ...shouldIgnoreFallbackImage ? rest : omit(rest, [\"onError\", \"onLoad\"])\n  };\n  if (showFallbackImage) {\n    if (fallback)\n      return fallback;\n    return /* @__PURE__ */ jsx(\n      chakra.img,\n      {\n        as: NativeImage,\n        className: \"chakra-image__placeholder\",\n        src: fallbackSrc,\n        ...shared\n      }\n    );\n  }\