r\n  };\r\n\r\n  const handleAddEvent = () => {\r\n    if (!newEvent.title.trim()) {\r\n      toast({ title: 'Error', description: 'Event title is required.', status: 'error', duration: 3000 });\r\n      return;\r\n    }\r\n    const dateString = selectedDate.toDateString();\r\n    const updatedEvents = { ...events };\r\n    if (!updatedEvents[dateString]) {\r\n      updatedEvents[dateString] = [];\r\n    }\r\n    updatedEvents[dateString].push(newEvent);\r\n    setEvents(updatedEvents);\r\n    setIsModalOpen(false);\r\n    setNewEvent({ title: '', time: '', description: '' });\r\n    toast({ title: 'Success', description: 'Event added!', status: 'success', duration: 3000 });\r\n  };\r\n\r\n  const tileContent = ({ date, view }) => {\r\n    if (view === 'month') {\r\n      const dateString = date.toDateString();\r\n      const dayEvents = events[dateString] || [];\r\n      if (dayEvents.length > 0) {\r\n        return dayEvents.map((event, index) => (\r\n          <Tooltip key={index} label={event.title} hasArrow placement=\"top\">\r\n            <Box\r\n              as=\"span\"\r\n              w=\"8px\"\r\n              h=\"8px\"\r\n              borderRadius=\"full\"\r\n              bg={getColorForEvent(index)}\r\n              mr={1}\r\n              display=\"inline-block\"\r\n            />\r\n          </Tooltip>\r\n        ));\r\n      }\r\n    }\r\n    return null;\r\n  };\r\n\r\n  const getColorForEvent = (index) => {\r\n    const colors = ['blue.500', 'purple.500', 'yellow.500', 'pink.500'];\r\n    return colors[index % colors.length];\r\n  };\r\n\r\n  return (\r\n    <Box\r\n      bg=\"white\"\r\n      borderRadius=\"md\"\r\n      boxShadow=\"md\"\r\n      p={6}\r\n      maxW={{ base: '100%', md: '800px' }}\r\n      mx=\"auto\"\r\n      width=\"100%\"\r\n      borderWidth=\"1px\"\r\n      borderColor=\"gray.200\"\r\n    >\r\n      <Text fontSize=\"xl\" fontWeight=\"bold\" textAlign=\"center\" mb={4}>\r\n        {date.toLocaleString('default', { month: 'long', year: 'numeric' })}  {/* Centered bold title */}\r\n      </Text>\r\n      <Calendar\r\n        onChange={setDate}\r\n        value={date}\r\n        onClickDay={handleDateClick}\r\n        tileContent={tileContent}\r\n        tileClassName={({ date: tileDate }) =>\r\n          tileDate.toDateString() === new Date().toDateString() ? 'highlight' : null  // Highlight today's date\r\n        }\r\n        prevLabel={<IconButton icon={<ChevronLeftIcon />} aria-label=\"Previous Month\" />}\r\n        nextLabel={<IconButton icon={<ChevronRightIcon />} aria-label=\"Next Month\" />}\r\n        formatMonthYear={(locale, date) => date.toLocaleString(locale, { month: 'long', year: 'numeric' })}\r\n      />\r\n      <Modal isOpen={isModalOpen} onClose={() => setIsModalOpen(false)}>\r\n        <ModalOverlay />\r\n        <ModalContent>\r\n          <ModalHeader>Add Event for {selectedDate?.toDateString()}</ModalHeader>\r\n          <ModalBody>\r\n            <Input\r\n              placeholder=\"Event Title\"\r\n              value={newEvent.title}\r\n              onChange={(e) => setNewEvent({ ...newEvent, title: e.target.value })}\r\n              mb={3}\r\n            />\r\n            <Input\r\n              placeholder=\"Time (optional)\"\r\n              value={newEvent.time}\r\n              onChange={(e) => setNewEvent({ ...newEvent, time: e.target.value })}\r\n              mb={3}\r\n            />\r\n            <Textarea\r\n              placeholder=\"Description (optional)\"\r\n              value={newEvent.description}\r\n              onChange={(e) => setNewEvent({ ...newEvent, description: e.target.value })}\r\n              mb={3}\r\n            />\r\n          </ModalBody>\r\n          <ModalFooter>\r\n            <Button onClick={handleAddEvent}>Save Event</Button>\r\n          </ModalFooter>\r\n        </ModalContent>\r\n      </Modal>\r\n    </Box>\r\n  );\r\n};\r\n\r\nexport default EventCalendar;\r\n","import React, { useEffect, useState } from 'react';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { auth } from '../services/api'; // Assuming auth service is still used\r\nimport Slider from 'react-slick';\r\nimport \"slick-carousel/slick/slick.css\";\r\nimport \"slick-carousel/slick/slick-theme.css\";\r\nimport Calendar from 'react-calendar';\r\nimport {\r\n  Box,\r\n  Flex,\r\n  Heading,\r\n  Text,\r\n  Button,\r\n  useToast,\r\n  useColorModeValue,\r\n  Spinner,\r\n  Divider,\r\n  SimpleGrid,\r\n  Stat,\r\n  StatLabel,\r\n  StatNumber,\r\n  Avatar,\r\n  Stack,\r\n  Icon,\r\n  HStack,\r\n  IconButton,\r\n  Input,\r\n  Textarea,\r\n  VStack\r\n} from '@chakra-ui/react';\r\nimport { FaSolarPanel, FaUsers, FaLeaf, FaArrowLeft, FaDownload, FaStar } from 'react-icons/fa';\r\nimport { jsPDF } from \"jspdf\";\r\nimport { motion } from 'framer-motion';\r\nimport './ImpactPage.css';  // Assuming we'll create a new CSS file for print styles, or add inline if needed\r\nimport EventCalendar from '../components/EventCalendar';  // New import for the calendar component\r\n\r\nfunction generateImpactReportPDF() {\r\n  const doc = new jsPDF();\r\n\r\n  doc.setFontSize(18);\r\n  doc.text(\"Gridx Impact Report\", 20, 20);\r\n\r\n  doc.setFontSize(12);\r\n  doc.text(\"Total Solar Energy Provided: 1.2M kWh saved\", 20, 40);\r\n  doc.text(\"Households Served: 4,300+ families empowered\", 20, 50);\r\n  doc.text(\"CO₂ Emissions Reduced: 620 tons offset\", 20, 60);\r\n\r\n  doc.save(\"impact_report.pdf\");\r\n}\r\n\r\nfunction ImpactPage() {\r\n  const navigate = useNavigate();\r\n  const toast = useToast();\r\n  const user = auth.getCurrentUser();\r\n  const [quote, setQuote] = useState('');\r\n  const [name, setName] = useState('');\r\n  const [email, setEmail] = useState('');\r\n  const [rating, setRating] = useState(0);\r\n  const [testimonials, setTestimonials] = useState(() => {\r\n    // Ignore localStorage for now to always show the new profiles\r\n    return [\r\n      { name: 'Emily Johnson', quote: 'GridX made solar simple for my family!', avatar: 'https://images.unsplash.com/photo-1511367461989-f85a21fda167', rating: 5 },\r\n      { name: 'Michael Smith', quote: 'Fantastic support and easy to use.', avatar: 'https://images.unsplash.com/photo-1508214751196-bcfd4ca60f91', rating: 4 },\r\n      { name: 'Jessica Brown', quote: 'I love tracking my energy savings.', avatar: 'https://images.unsplash.com/photo-1517841905240-472988babdf9', rating: 5 },\r\n      { name: 'David Wilson', quote: 'Solar energy has never been easier.', avatar: 'https://images.unsplash.com/photo-1529626455594-4ff0802cfb7e', rating: 5 },\r\n      { name: 'Ashley Miller', quote: 'GridX is a game changer for my home.', avatar: 'https://images.unsplash.com/photo-1464983953574-0892a716854b', rating: 4 },\r\n      { name: 'Matthew Davis', quote: 'Highly recommend to anyone going solar.', avatar: 'https://images.unsplash.com/photo-1519340333755-c2f6c58f5c4b', rating: 5 },\r\n      { name: 'Hannah Moore', quote: 'Easy to use and very informative.', avatar: 'https://images.unsplash.com/photo-1519125323398-675f0ddb6308', rating: 4 },\r\n      { name: 'Christopher Taylor', quote: 'Great for monitoring my energy use.', avatar: 'https://images.unsplash.com/photo-1507003211169-0a1dd7228f2d', rating: 5 },\r\n      { name: 'Lauren Anderson', quote: 'The best app for solar households.', avatar: 'https://images.unsplash.com/photo-1511367461989-f85a21fda167', rating: 5 },\r\n      { name: 'Daniel Thomas', quote: 'I appreciate the detailed analytics.', avatar: 'https://images.unsplash.com/photo-1508214751196-bcfd4ca60f91', rating: 4 },\r\n      { name: 'Olivia Jackson', quote: 'My bills have dropped thanks to Gridx.', avatar: 'https://images.unsplash.com/photo-1517841905240-472988babdf9', rating: 5 },\r\n      { name: 'James White', quote: 'Setup was quick and painless.', avatar: 'https://images.unsplash.com/photo-1529626455594-4ff0802cfb7e', rating: 5 },\r\n      { name: 'Samantha Harris', quote: 'I love seeing my energy impact.', avatar: 'https://images.unsplash.com/photo-1464983953574-0892a716854b', rating: 4 },\r\n      { name: 'Benjamin Martin', quote: 'GridX is the future of home energy.', avatar: 'https://images.unsplash.com/photo-1519340333755-c2f6c58f5c4b', rating: 5 },\r\n      { name: 'Grace Lee', quote: 'So easy, even my kids use it!', avatar: 'https://images.unsplash.com/photo-1519125323398-675f0ddb6308', rating: 5 }\r\n    ];\r\n  });\r\n\r\n  const isValidEmail = (email) => {\r\n    const emailRegex = /^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$/;\r\n    return emailRegex.test(email);\r\n  };\r\n\r\n  const handleSubmit = async (e) => {\r\n    e.preventDefault();\r\n    if (!name) {\r\n      toast({ title: 'Error', description: 'Name is required.', status: 'error', duration: 3000, isClosable: true });\r\n      return;\r\n    }\r\n    if (!email || !isValidEmail(email)) {\r\n      toast({ title: 'Error', description: 'A valid Email is required.', status: 'error', duration: 3000, isClosable: true });\r\n      return;\r\n    }\r\n    if (!quote) {\r\n      toast({ title: 'Error', description: 'Testimonial is required.', status: 'error', duration: 3000, isClosable: true });\r\n      return;\r\n    }\r\n    \r\n    const newTestimonial = {\r\n      name,\r\n      quote,\r\n      email,\r\n      rating,\r\n      avatar: 'https://via.placeholder.com/150',\r\n    };\r\n    \r\n    try {\r\n      const updatedTestimonials = [...testimonials, newTestimonial];\r\n      setTestimonials(updatedTestimonials);\r\n      localStorage.setItem('testimonials', JSON.stringify(updatedTestimonials));\r\n      toast({ title: 'Story Submitted', description: 'Your story has been simulated successfully! (Not yet saved to database)', status: 'success', duration: 3000, isClosable: true });\r\n    } catch (error) {\r\n      toast({ title: 'Error', description: 'Submission failed. Please try again later.', status: 'error', duration: 3000, isClosable: true });\r\n      console.error('Submission error:', error);\r\n    }\r\n    \r\n    setName('');\r\n    setEmail('');\r\n    setQuote('');\r\n    setRating(0);\r\n  };\r\n\r\n  const bgColor = useColorModeValue('gray.50', 'gray.700');\r\n  const textColor = useColorModeValue('gray.800', 'whiteAlpha.900');\r\n  const statColor = useColorModeValue('teal.500', 'teal.300');\r\n  const testimonialBg = useColorModeValue('white', 'gray.800');\r\n  const testimonialBorderColor = useColorModeValue('gray.200', 'gray.600');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const subTextColor = useColorModeValue('gray.600', 'whiteAlpha.700');\r\n\r\n  const MotionIcon = motion(Icon);\r\n\r\n  useEffect(() => {\r\n    if (!user) {\r\n      navigate('/login');\r\n      toast({\r\n        title: 'Authentication required.',\r\n        description: \"Please log in to view the impact.\",\r\n        status: 'warning',\r\n        duration: 3000,\r\n        isClosable: true,\r\n      });\r\n    }\r\n  }, [user, navigate, toast]);\r\n\r\n  useEffect(() => {\r\n    console.log('Number of testimonials:', testimonials.length);\r\n  }, [testimonials]);\r\n\r\n  const impactStats = [\r\n    { label: 'Total Solar Energy Provided', value: '1.2M kWh saved', icon: FaSolarPanel },\r\n    { label: 'Households Served', value: '4,300+ families empowered', icon: FaUsers },\r\n    { label: 'CO₂ Emissions Reduced', value: '620 tons offset', icon: FaLeaf },\r\n  ];\r\n\r\n  function handleRate(testimonialIndex, newRating) {\r\n    const updatedTestimonials = [...testimonials];\r\n    updatedTestimonials[testimonialIndex].rating = newRating;\r\n    setTestimonials(updatedTestimonials);\r\n    localStorage.setItem('testimonials', JSON.stringify(updatedTestimonials));\r\n  }\r\n\r\n  if (!user) {\r\n    return (\r\n      <Flex minH=\"100vh\" align=\"center\" justify=\"center\" bg={bgColor}>\r\n        <Spinner size=\"xl\" color={statColor} />\r\n      </Flex>\r\n    );\r\n  }\r\n\r\n  return (\r\n    <Box\r\n      minH=\"100vh\"\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\"\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\"\r\n      position=\"relative\"\r\n      _before={{\r\n        content: '\"\"',\r\n        position: 'absolute',\r\n        top: 0,\r\n        left: 0,\r\n        right: 0,\r\n        bottom: 0,\r\n        bg: 'rgba(0, 0, 0, 0.5)',\r\n        zIndex: 1,\r\n      }}\r\n    >\r\n      <Box p={[4, 6, 8]} maxWidth=\"1200px\" mx=\"auto\" color={textColor} position=\"relative\" zIndex={2}>\r\n        <HStack justify=\"space-between\" align=\"center\" mb={8}>\r\n          <Button\r\n            leftIcon={<FaArrowLeft />}\r\n            variant=\"ghost\"\r\n            onClick={() => navigate('/home')}\r\n            color={headingColor}\r\n          >\r\n            Back to Home\r\n          </Button>\r\n          <Button\r\n            onClick={() => window.print()}\r\n            colorScheme=\"teal\"\r\n            leftIcon={<FaDownload />}\r\n          >\r\n            Print Page\r\n          </Button>\r\n        </HStack>\r\n\r\n        <Heading as=\"h1\" size=\"xl\" color={headingColor} mb={6}>\r\n          Environmental Impact\r\n        </Heading>\r\n\r\n        <Stack spacing={10}>\r\n          <Box>\r\n            <Heading as=\"h2\" size=\"lg\" mb={4}>Impact Statistics</Heading>\r\n            <SimpleGrid columns={{ base: 1, md: 3 }} spacing={6}>\r\n              {impactStats.map((stat, index) => (\r\n                <Box\r\n                  key={index}\r\n                  p={6}\r\n                  boxShadow=\"md\"\r\n                  borderRadius=\"lg\"\r\n                  bg={testimonialBg}\r\n                  borderColor={testimonialBorderColor}\r\n                  borderWidth=\"1px\"\r\n                >\r\n                  <Flex align=\"center\" mb={2}>\r\n                    <Icon as={stat.icon} w={8} h={8} color={statColor} mr={3} />\r\n                    <Stat>\r\n                      <StatLabel fontSize=\"md\">{stat.label}</StatLabel>\r\n                      <StatNumber>{stat.value}</StatNumber>\r\n                    </Stat>\r\n                  </Flex>\r\n                </Box>\r\n              ))}\r\n            </SimpleGrid>\r\n          </Box>\r\n\r\n          <Divider />\r\n\r\n          <Box>\r\n            <Heading as=\"h2\" size=\"lg\" mb={4}>Upcoming Events Calendar</Heading>\r\n            <EventCalendar />\r\n          </Box>\r\n\r\n          <Divider />\r\n\r\n          <Box>\r\n            <Heading as=\"h2\" size=\"lg\" mb={4}>Community Voices</Heading>\r\n            <Slider\r\n              dots={true}\r\n              infinite={true}\r\n              speed={500}\r\n              slidesToShow={1}\r\n              slidesToScroll={1}\r\n              autoplay={true}\r\n              autoplaySpeed={3000}\r\n              accessibility={true}\r\n            >\r\n              {testimonials.map((testimonial, index) => (\r\n                <Box key={testimonial.name} p={6} bg={testimonialBg} borderWidth=\"1px\" borderColor={testimonialBorderColor} borderRadius=\"lg\" boxShadow=\"md\">\r\n                  <Flex align=\"center\" mb={4}>\r\n                    <Avatar src={testimonial.avatar} name={testimonial.name} size=\"xl\" mr={4} />\r\n                    <VStack align=\"start\" flex=\"1\">\r\n                      <Text fontSize=\"lg\" fontStyle=\"italic\" color={textColor}>\"{testimonial.quote}\"</Text>\r\n                      <HStack mt={2}>\r\n                        {Array(5).fill('').map((_, starIndex) => (\r\n                          <MotionIcon\r\n                            as={FaStar}\r\n                            key={starIndex}\r\n                            color={starIndex < testimonial.rating ? 'yellow.400' : 'gray.300'}\r\n                            boxSize={6}\r\n                            onClick={() => handleRate(index, starIndex + 1)}\r\n                            cursor=\"pointer\"\r\n                            initial={{ scale: 1 }}\r\n                            animate={testimonial.rating === 5 && starIndex === 4 ? { scale: [1, 1.5, 1], rotate: [0, 360, 0], transition: { duration: 0.5 } } : { scale: 1 }}\r\n                          />\r\n                        ))}\r\n                      </HStack>\r\n                      <Text fontWeight=\"bold\" fontSize=\"md\" color={subTextColor}>{testimonial.name}</Text>\r\n                    </VStack>\r\n                  </Flex>\r\n                </Box>\r\n              ))}\r\n            </Slider>\r\n          </Box>\r\n\r\n          <Divider />\r\n\r\n          <Box textAlign=\"center\">\r\n            <Heading as=\"h2\" size=\"lg\" mb={4}>Why Solar + Fintech Matters</Heading>\r\n            <Text fontSize=\"lg\" maxWidth=\"800px\" mx=\"auto\">\r\n              Access to clean, affordable energy is transformative. By combining solar technology with accessible fintech solutions, we empower individuals and communities, drive economic growth, and build a sustainable future. Every watt saved and every household powered contributes to a brighter tomorrow.\r\n            </Text>\r\n          </Box>\r\n\r\n          <Box textAlign=\"center\" mt={10}>\r\n            <form onSubmit={handleSubmit}>\r\n              <Stack spacing={4} maxWidth=\"400px\" mx=\"auto\">\r\n                <Heading as=\"h2\" size=\"md\" mb={4}>Share Your Story</Heading>\r\n                <Input\r\n                  placeholder=\"Your Name\"\r\n                  value={name}\r\n                  onChange={(e) => setName(e.target.value)}\r\n                  isRequired\r\n                />\r\n                <Input\r\n                  placeholder=\"Your Email\"\r\n                  value={email}\r\n                  onChange={(e) => setEmail(e.target.value)}\r\n                  type=\"email\"\r\n                />\r\n                <Textarea\r\n                  placeholder=\"Share your story or testimonial\"\r\n                  value={quote}\r\n                  onChange={(e) => setQuote(e.target.value)}\r\n                  isRequired\r\n                />\r\n                <Button type=\"submit\" colorScheme=\"teal\">Share Your Story</Button>\r\n              </Stack>\r\n            </form>\r\n          </Box>\r\n        </Stack>\r\n      </Box>\r\n\r\n      <Box\r\n        position=\"fixed\"\r\n        bottom=\"90px\"\r\n        right=\"24px\"\r\n        zIndex=\"9999\"\r\n      >\r\n        <IconButton\r\n          aria-label=\"Download Impact Report\"\r\n          icon={<FaDownload />}\r\n          size=\"lg\"\r\n          colorScheme=\"teal\"\r\n          isRound\r\n          boxShadow=\"lg\"\r\n          onClick={() => {\r\n            generateImpactReportPDF();\r\n            toast({\r\n              title: 'Report downloaded',\r\n              description: 'Your impact report has been downloaded successfully.',\r\n              status: 'success',\r\n              duration: 3000,\r\n              isClosable: true,\r\n            });\r\n          }}\r\n        />\r\n      </Box>\r\n    </Box>\r\n  );\r\n}\r\n\r\nexport default ImpactPage; ","import React, { useState } from 'react';\r\nimport {\r\n  Box,\r\n  Container,\r\n  Heading,\r\n  Button,\r\n  VStack,\r\n  useColorModeValue,\r\n  Flex,\r\n  Icon,\r\n  Text,\r\n  SimpleGrid,\r\n  Badge,\r\n} from '@chakra-ui/react';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { FaArrowLeft, FaMoneyBill, FaChartLine, FaCalendarAlt } from 'react-icons/fa';\r\n\r\nconst ExpensesPage = () => {\r\n  const navigate = useNavigate();\r\n  \r\n  // Move all useColorModeValue hooks to the top level\r\n  const cardBg = useColorModeValue('white', 'gray.700');\r\n  const textColor = useColorModeValue('gray.800', 'white');\r\n  const itemBg = useColorModeValue('gray.50', 'gray.600');\r\n  const subTextColor = useColorModeValue('gray.600', 'gray.300');\r\n\r\n  // Mock data for expenses\r\n  const [expenses] = useState([\r\n    {\r\n      id: 1,\r\n      date: '2024-03-15',\r\n      amount: 150.00,\r\n      category: 'Electricity',\r\n      status: 'Paid'\r\n    },\r\n    {\r\n      id: 2,\r\n      date: '2024-03-10',\r\n      amount: 75.50,\r\n      category: 'Solar Maintenance',\r\n      status: 'Pending'\r\n    },\r\n    {\r\n      id: 3,\r\n      date: '2024-03-05',\r\n      amount: 200.00,\r\n      category: 'Equipment',\r\n      status: 'Paid'\r\n    }\r\n  ]);\r\n\r\n  return (\r\n    <Box\r\n      minH=\"100vh\"\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\"\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\"\r\n      position=\"relative\"\r\n      _before={{\r\n        content: '\"\"',\r\n        position: \"absolute\",\r\n        top: 0,\r\n        left: 0,\r\n        right: 0,\r\n        bottom: 0,\r\n        bg: \"rgba(0, 0, 0, 0.5)\",\r\n        zIndex: 1,\r\n      }}\r\n    >\r\n      <Container maxW=\"container.xl\" py={8} position=\"relative\" zIndex={2}>\r\n        <Button\r\n          leftIcon={<FaArrowLeft />}\r\n          variant=\"ghost\"\r\n          mb={8}\r\n          onClick={() => navigate('/home')}\r\n          color=\"white\"\r\n          _hover={{ bg: 'whiteAlpha.200' }}\r\n        >\r\n          Back to Home\r\n        </Button>\r\n\r\n        <VStack spacing={8} align=\"stretch\">\r\n          <Heading size=\"xl\" color=\"white\">Expenses</Heading>\r\n\r\n          {/* Summary Cards */}\r\n          <SimpleGrid columns={{ base: 1, md: 3 }} spacing={6}>\r\n            <Box p={6} bg={cardBg} borderRadius=\"lg\" shadow=\"md\">\r\n              <Flex align=\"center\" mb={4}>\r\n                <Icon as={FaMoneyBill} w={6} h={6} color=\"green.500\" mr={3} />\r\n                <Text fontSize=\"lg\" fontWeight=\"bold\" color={textColor}>Total Expenses</Text>\r\n              </Flex>\r\n              <Text fontSize=\"2xl\" fontWeight=\"bold\" color=\"green.500\">\r\n                R{expenses.reduce((sum, exp) => sum + exp.amount, 0).toFixed(2)}\r\n              </Text>\r\n            </Box>\r\n\r\n            <Box p={6} bg={cardBg} borderRadius=\"lg\" shadow=\"md\">\r\n              <Flex align=\"center\" mb={4}>\r\n                <Icon as={FaChartLine} w={6} h={6} color=\"blue.500\" mr={3} />\r\n                <Text fontSize=\"lg\" fontWeight=\"bold\" color={textColor}>Monthly Average</Text>\r\n              </Flex>\r\n              <Text fontSize=\"2xl\" fontWeight=\"bold\" color=\"blue.500\">\r\n                R{(expenses.reduce((sum, exp) => sum + exp.amount, 0) / expenses.length).toFixed(2)}\r\n              </Text>\r\n            </Box>\r\n\r\n            <Box p={6} bg={cardBg} borderRadius=\"lg\" shadow=\"md\">\r\n              <Flex align=\"center\" mb={4}>\r\n                <Icon as={FaCalendarAlt} w={6} h={6} color=\"purple.500\" mr={3} />\r\n                <Text fontSize=\"lg\" fontWeight=\"bold\" color={textColor}>Last Payment</Text>\r\n              </Flex>\r\n              <Text fontSize=\"2xl\" fontWeight=\"bold\" color=\"purple.500\">\r\n                {expenses[0].date}\r\n              </Text>\r\n            </Box>\r\n          </SimpleGrid>\r\n\r\n          {/* Expenses List */}\r\n          <Box p={6} bg={cardBg} borderRadius=\"lg\" shadow=\"md\">\r\n            <Heading size=\"md\" mb={4} color={textColor}>Recent Expenses</Heading>\r\n            <VStack spacing={4} align=\"stretch\">\r\n              {expenses.map((expense) => (\r\n                <Flex\r\n                  key={expense.id}\r\n                  justify=\"space-between\"\r\n                  align=\"center\"\r\n                  p={4}\r\n                  bg={itemBg}\r\n                  borderRadius=\"md\"\r\n                >\r\n                  <Box>\r\n                    <Text fontWeight=\"bold\" color={textColor}>{expense.category}</Text>\r\n                    <Text fontSize=\"sm\" color={subTextColor}>\r\n                      {expense.date}\r\n                    </Text>\r\n                  </Box>\r\n                  <Box textAlign=\"right\">\r\n                    <Text fontWeight=\"bold\" color={textColor}>R{expense.amount.toFixed(2)}</Text>\r\n                    <Badge\r\n                      colorScheme={expense.status === 'Paid' ? 'green' : 'yellow'}\r\n                    >\r\n                      {expense.status}\r\n                    </Badge>\r\n                  </Box>\r\n                </Flex>\r\n              ))}\r\n            </VStack>\r\n          </Box>\r\n        </VStack>\r\n      </Container>\r\n    </Box>\r\n  );\r\n};\r\n\r\nexport default ExpensesPage;\r\n","import React, { useState, useEffect } from 'react';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { auth } from '../services/api';\r\n\r\n// Import Chakra UI Components\r\nimport {\r\n  Box,\r\n  Flex,\r\n  Heading,\r\n  Text,\r\n  Button,\r\n  useColorModeValue,\r\n  useToast,\r\n  Spinner,\r\n  Container,\r\n  Stack,\r\n  Alert,\r\n  AlertIcon,\r\n  AlertTitle,\r\n  AlertDescription,\r\n  CloseButton,\r\n  HStack\r\n} from '@chakra-ui/react';\r\n\r\n// Import Icons\r\nimport { FaArrowLeft } from 'react-icons/fa';\r\n\r\nfunction NotificationsPage() {\r\n  const navigate = useNavigate();\r\n  const toast = useToast();\r\n  const user = auth.getCurrentUser();\r\n\r\n  // Color mode values\r\n  const bgColor = useColorModeValue('gray.50', 'gray.900');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const textColor = useColorModeValue('gray.600', 'gray.400');\r\n\r\n  // Dummy notification data\r\n  const [notifications, setNotifications] = useState([\r\n    { id: 1, status: 'warning', title: 'Low Balance', description: 'Your energy credit is running low. Top up soon!', isDismissed: false },\r\n    { id: 2, status: 'info', title: 'System Update', description: 'Scheduled maintenance tonight at 2 AM.', isDismissed: false },\r\n    { id: 3, status: 'success', title: 'Top-Up Successful', description: 'Your R200 top-up was successful.', isDismissed: false },\r\n    { id: 4, status: 'error', title: 'Payment Failed', description: 'Your recent payment failed. Please check your details.', isDismissed: false },\r\n  ]);\r\n\r\n  // Redirect if not authenticated\r\n  useEffect(() => {\r\n    if (!user) {\r\n      navigate('/login');\r\n      toast({\r\n        title: 'Authentication required',\r\n        description: 'Please log in to access this page',\r\n        status: 'warning',\r\n        duration: 3000,\r\n        isClosable: true,\r\n      });\r\n    }\r\n  }, [user, navigate, toast]);\r\n\r\n  const handleDismissNotification = (id) => {\r\n    setNotifications(notifications.map(notif =>\r\n      notif.id === id ? { ...notif, isDismissed: true } : notif\r\n    ));\r\n  };\r\n\r\n  const activeNotifications = notifications.filter(notif => !notif.isDismissed);\r\n\r\n  if (!user) {\r\n    return (\r\n      <Flex minH=\"100vh\" align=\"center\" justify=\"center\" bg={bgColor}>\r\n        <Spinner size=\"xl\" color=\"blue.500\" />\r\n      </Flex>\r\n    );\r\n  }\r\n\r\n  return (\r\n    <Box\r\n      minH=\"100vh\"\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\"\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\"\r\n      position=\"relative\"\r\n      _before={{\r\n          content: '\"\"',\r\n          position: 'absolute',\r\n          top: 0,\r\n          left: 0,\r\n          right: 0,\r\n          bottom: 0,\r\n          bg: 'rgba(0, 0, 0, 0.5)',\r\n          zIndex: 1,\r\n      }}\r\n    >\r\n      <Container maxW=\"container.xl\" py={8} position=\"relative\" zIndex={2}>\r\n        {/* Header with Back to Home button */}\r\n        <HStack justify=\"space-between\" align=\"center\" mb={8}>\r\n           <Button\r\n            leftIcon={<FaArrowLeft />}\r\n            variant=\"ghost\"\r\n            onClick={() => navigate('/home')}\r\n            color={headingColor}\r\n          >\r\n            Back to Home\r\n          </Button>\r\n        </HStack>\r\n\r\n        <Heading as=\"h1\" size=\"xl\" color={headingColor} mb={6} textAlign=\"center\">\r\n          Notifications\r\n        </Heading>\r\n\r\n        <Stack spacing={4}>\r\n          {activeNotifications.length > 0 ? (\r\n            activeNotifications.map((notif) => (\r\n              <Alert\r\n                key={notif.id}\r\n                status={notif.status}\r\n                variant=\"left-accent\"\r\n                pr={10} // Add padding to the right to make space for the close button\r\n              >\r\n                <AlertIcon />\r\n                <Box flex=\"1\">\r\n                  <AlertTitle mt={-1} mb={1} fontSize=\"md\">{notif.title}</AlertTitle>\r\n                  <AlertDescription display=\"block\">{notif.description}</AlertDescription>\r\n                </Box>\r\n                <CloseButton\r\n                  position=\"absolute\"\r\n                  right=\"8px\"\r\n                  top=\"8px\"\r\n                  onClick={() => handleDismissNotification(notif.id)}\r\n                />\r\n              </Alert>\r\n            ))\r\n          ) : (\r\n            <Text textAlign=\"center\" mt={8} color={textColor}>No new notifications.</Text>\r\n          )}\r\n        </Stack>\r\n\r\n      </Container>\r\n    </Box>\r\n  );\r\n}\r\n\r\nexport default NotificationsPage;\r\n","'use client';\nimport { useLayoutEffect, useEffect } from 'react';\n\nfunction sortNodes(nodes) {\n  return nodes.sort((a, b) => {\n    const compare = a.compareDocumentPosition(b);\n    if (compare & Node.DOCUMENT_POSITION_FOLLOWING || compare & Node.DOCUMENT_POSITION_CONTAINED_BY) {\n      return -1;\n    }\n    if (compare & Node.DOCUMENT_POSITION_PRECEDING || compare & Node.DOCUMENT_POSITION_CONTAINS) {\n      return 1;\n    }\n    if (compare & Node.DOCUMENT_POSITION_DISCONNECTED || compare & Node.DOCUMENT_POSITION_IMPLEMENTATION_SPECIFIC)