// Default category\r\n  });\r\n\r\n  // Array of motivational lines\r\n  const motivationalLines = useMemo(() => [\r\n    \"Unlock exclusive savings by joining forces with other buyers!\",\r\n    \"Group buying: the smart way to go solar and save big!\",\r\n    \"Lower your costs, increase your impact – together we power change.\",\r\n    \"Get premium solar gear at unbeatable group prices.\",\r\n    \"Join a campaign and step closer to energy independence.\",\r\n    \"Your next energy upgrade is more affordable with group power.\",\r\n    \"Connect with fellow solar enthusiasts and save together.\",\r\n    \"Every participant helps drive down the price for everyone.\",\r\n    \"Don't miss out on limited-time group buying opportunities.\",\r\n    \"Investing in solar is easier and cheaper in a group.\",\r\n  ], []);\r\n\r\n  // State for current line index and the key for AnimatePresence\r\n  const [currentLineIndex, setCurrentLineIndex] = useState(0);\r\n  const [animationKey, setAnimationKey] = useState(0); // Key to trigger exit/enter animation\r\n\r\n  // Effect to rotate lines every 7 seconds\r\n  useEffect(() => {\r\n    const interval = setInterval(() => {\r\n      setCurrentLineIndex((prevIndex) =>\r\n        prevIndex === motivationalLines.length - 1 ? 0 : prevIndex + 1\r\n      );\r\n      setAnimationKey(prevKey => prevKey + 1); // Update key to trigger re-render and animation\r\n    }, 7000);\r\n\r\n    return () => clearInterval(interval); // Clean up interval on component unmount\r\n  }, [motivationalLines.length]); // Re-run if the number of lines changes\r\n\r\n  // Animation variants for fade in/out\r\n  const fadeVariants = {\r\n    initial: { opacity: 0 },\r\n    animate: { opacity: 1 },\r\n    exit: { opacity: 0 },\r\n  };\r\n\r\n  // Color mode values\r\n  const textColor = useColorModeValue('gray.800', 'whiteAlpha.900');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const inputBgColor = useColorModeValue('white', 'gray.800');\r\n  const inputBorderColor = useColorModeValue('gray.300', 'gray.600');\r\n\r\n  // Define colors for glassmorphism effect on cards\r\n  const glassCardBg = useColorModeValue('rgba(255, 255, 255, 0.15)', 'rgba(26, 32, 44, 0.15)');\r\n  const glassBorderColor = useColorModeValue('rgba(255, 255, 255, 0.2)', 'rgba(255, 255, 255, 0.1)');\r\n  const glassBoxShadow = useColorModeValue('0 4px 12px rgba(0, 0, 0, 0.15)', '0 4px 12px rgba(0, 0, 0, 0.5)'); // Adjust shadow for depth\r\n\r\n  // Define hover box shadow using useColorModeValue at the top level\r\n  const hoverBoxShadow = useColorModeValue('0 8px 16px rgba(0, 0, 0, 0.2)', '0 8px 16px rgba(0, 0, 0, 0.6)');\r\n\r\n  const handleInputChange = (e) => {\r\n    const { name, value } = e.target;\r\n    setNewCampaign({\r\n      ...newCampaign,\r\n      [name]: value,\r\n    });\r\n  };\r\n\r\n  const handleNumberInputChange = (name, valueString) => {\r\n    const value = parseFloat(valueString);\r\n    setNewCampaign({\r\n      ...newCampaign,\r\n      [name]: isNaN(value) ? 0 : value,\r\n    });\r\n  };\r\n\r\n  const handleJoinCampaign = (campaignId) => {\r\n    console.log(`Joining campaign with ID: ${campaignId}`);\r\n    setOngoingCampaigns(ongoingCampaigns.map(campaign =>\r\n        campaign.id === campaignId ? { ...campaign, participants: campaign.participants + 1 } : campaign\r\n    ));\r\n    toast({\r\n      title: 'Joined Campaign!',\r\n      description: 'You have successfully joined the group buying campaign.',\r\n      status: 'success',\r\n      duration: 3000,\r\n      isClosable: true,\r\n    });\r\n  };\r\n\r\n  const handleCreateCampaign = (e) => {\r\n    e.preventDefault();\r\n    console.log('Creating new campaign:', newCampaign);\r\n\r\n    // Adjusted validation to check if image is null or empty string\r\n    if (!newCampaign.product || newCampaign.targetBuyers <= 0 || newCampaign.originalPrice <= 0 || !newCampaign.deadline || !newCampaign.image) {\r\n        toast({\r\n            title: 'Creation failed.',\r\n            description: 'Please fill in all campaign details correctly, including image.',\r\n            status: 'error',\r\n            duration: 5000,\r\n            isClosable: true,\r\n        });\r\n        return;\r\n    }\r\n\r\n    const newCampaignWithMockData = {\r\n      ...newCampaign,\r\n      id: ongoingCampaigns.length + 1,\r\n      participants: 0,\r\n      timeLeft: 'Just started!', // Mock value for new campaign\r\n      icon: FaSolarPanel // Default icon, could be dynamic based on category\r\n    };\r\n    setOngoingCampaigns([...ongoingCampaigns, newCampaignWithMockData]);\r\n\r\n    toast({\r\n      title: 'Campaign Created!',\r\n      description: `${newCampaign.product} campaign has been created.`,\r\n      status: 'success',\r\n      duration: 3000,\r\n      isClosable: true,\r\n    });\r\n\r\n    setNewCampaign({\r\n      product: '',\r\n      description: '',\r\n      originalPrice: 0,\r\n      groupPrice: 0,\r\n      targetBuyers: 10,\r\n      deadline: '',\r\n      image: null,\r\n      category: 'Solar Panels'\r\n    });\r\n    setSelectedImage(null);\r\n    onClose(); // Close the modal after creation\r\n  };\r\n\r\n  const handleImageChange = (e) => {\r\n    const file = e.target.files[0];\r\n    if (file) {\r\n      const reader = new FileReader();\r\n      reader.onloadend = () => {\r\n        setSelectedImage(reader.result);\r\n        setNewCampaign({\r\n          ...newCampaign,\r\n          image: reader.result, // Store image as base64 or URL\r\n        });\r\n      };\r\n      reader.readAsDataURL(file); // Read file as data URL for preview\r\n    }\r\n  };\r\n\r\n  return (\r\n    <Box\r\n      minH=\"100vh\"\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\"\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\"\r\n      position=\"relative\"\r\n      _before={{\r\n          content: '\"\"',\r\n          position: 'absolute',\r\n          top: 0,\r\n          left: 0,\r\n          right: 0,\r\n          bottom: 0,\r\n          bg: 'rgba(0, 0, 0, 0.5)',\r\n          zIndex: 1,\r\n      }}\r\n    >\r\n      <Container maxW=\"container.lg\" py={8} position=\"relative\" zIndex={2}>\r\n        <VStack spacing={8} align=\"stretch\">\r\n          {/* Header Section */}\r\n          <HStack justify=\"space-between\" align=\"center\" mb={8}>\r\n            <Button\r\n              leftIcon={<FaArrowLeft />}\r\n              variant=\"ghost\"\r\n              onClick={() => navigate('/home')}\r\n              color={headingColor}\r\n            >\r\n              Back to Home\r\n            </Button>\r\n          </HStack>\r\n\r\n          <Heading size=\"xl\" color={headingColor} mb={2} textAlign=\"center\">Group Buying Campaigns</Heading>\r\n          <AnimatePresence mode=\"wait\">\r\n             <MotionText\r\n                key={animationKey}\r\n                color={textColor}\r\n                fontSize=\"lg\"\r\n                textAlign=\"center\"\r\n                mb={6}\r\n                variants={fadeVariants}\r\n                initial=\"initial\"\r\n                animate=\"animate\"\r\n                exit=\"exit\"\r\n                transition={{ duration: 0.5 }}\r\n             >\r\n               {motivationalLines[currentLineIndex]}\r\n             </MotionText>\r\n          </AnimatePresence>\r\n\r\n          {/* Campaigns List */}\r\n          <SimpleGrid columns={{ base: 1, md: 2, lg: 3 }} spacing={6}>\r\n            {ongoingCampaigns.map((campaign) => {\r\n              const progressValue = (campaign.participants / campaign.goal) * 100;\r\n              const savings = campaign.originalPrice - campaign.groupPrice;\r\n              const savingsPercentage = campaign.originalPrice > 0 ? ((savings / campaign.originalPrice) * 100).toFixed(0) : 0;\r\n\r\n              return (\r\n                <Card\r\n                  key={campaign.id}\r\n                  bg={glassCardBg}\r\n                  borderWidth=\"1px\"\r\n                  borderColor={glassBorderColor}\r\n                  boxShadow={glassBoxShadow}\r\n                  borderRadius=\"lg\"\r\n                  backdropFilter=\"blur(10px)\"\r\n                  transition=\"all 0.3s ease-in-out\"\r\n                  _hover={{\r\n                    transform: 'translateY(-5px)',\r\n                    boxShadow: hoverBoxShadow,\r\n                  }}\r\n                >\r\n                  <CardHeader p={0}>\r\n                    <Image\r\n                      src={campaign.image}\r\n                      alt={campaign.product}\r\n                      height=\"200px\"\r\n                      width=\"100%\"\r\n                      objectFit=\"cover\"\r\n                      borderTopRadius=\"lg\"\r\n                    />\r\n                  </CardHeader>\r\n                  <CardBody>\r\n                    <Flex align=\"center\" mb={2}>\r\n                      <Heading size=\"md\">{campaign.product}</Heading>\r\n                    </Flex>\r\n\r\n                    <VStack spacing={3} align=\"stretch\">\r\n                      <HStack justify=\"space-between\">\r\n                        <Text color={textColor}>\r\n                          <Icon as={FaTag} mr={2} />\r\n                          Original: R{campaign.originalPrice}\r\n                        </Text>\r\n                        {savingsPercentage > 0 && (\r\n                          <Badge colorScheme=\"green\" fontSize=\"md\">\r\n                            Save {savingsPercentage}%\r\n                          </Badge>\r\n                        )}\r\n                      </HStack>\r\n\r\n                      <Text fontSize=\"xl\" fontWeight=\"bold\" color=\"green.500\">\r\n                        Group Price: R{campaign.groupPrice}\r\n                      </Text>\r\n\r\n                      <Text color={textColor} noOfLines={2}>{campaign.description}</Text>\r\n\r\n                      <HStack>\r\n                        <Icon as={FaUsers} />\r\n                        <Text color={textColor}>\r\n                          {campaign.participants} of {campaign.goal} joined\r\n                        </Text>\r\n                      </HStack>\r\n\r\n                      <Progress value={progressValue} size=\"sm\" colorScheme=\"blue\" hasStripe isAnimated />\r\n\r\n                      <HStack>\r\n                        <Icon as={FaClock} />\r\n                        <Text color={textColor}>{campaign.timeLeft}</Text>\r\n                      </HStack>\r\n\r\n                      <Button\r\n                        colorScheme=\"green\"\r\n                        onClick={() => handleJoinCampaign(campaign.id)}\r\n                        isDisabled={campaign.participants >= campaign.goal}\r\n                        width=\"100%\"\r\n                        mt={4}\r\n                        transition=\"transform 0.2s ease-in-out\"\r\n                        _hover={{\r\n                            transform: 'scale(1.02)',\r\n                        }}\r\n                      >\r\n                        {campaign.participants >= campaign.goal ? 'Goal Reached!' : 'Join Campaign'}\r\n                      </Button>\r\n                       {/* Back to Home Button */}\r\n                      <Button variant=\"outline\" onClick={() => navigate('/home')} size=\"sm\" width=\"100%\" mt={2}>\r\n                         Back to Home\r\n                      </Button>\r\n                    </VStack>\r\n                  </CardBody>\r\n                </Card>\r\n              );\r\n            })}\r\n          </SimpleGrid>\r\n\r\n          {/* Create Campaign Button at bottom */}\r\n          <Box textAlign=\"center\" mt={8}>\r\n            <Button\r\n              colorScheme=\"teal\"\r\n              onClick={onOpen}\r\n              leftIcon={<Icon as={FaSolarPanel} />}\r\n              size=\"lg\"\r\n              width={{ base: \"full\", md: \"auto\" }}\r\n              transition=\"transform 0.2s ease-in-out\"\r\n              _hover={{\r\n                  transform: 'scale(1.05)',\r\n              }}\r\n            >\r\n              Create New Campaign\r\n            </Button>\r\n          </Box>\r\n        </VStack>\r\n      </Container>\r\n\r\n      {/* Create Campaign Modal */}\r\n      <Modal isOpen={isOpen} onClose={onClose} size=\"xl\">\r\n        <ModalOverlay />\r\n        <ModalContent>\r\n          <ModalHeader>Create New Solar Campaign</ModalHeader>\r\n          <ModalCloseButton />\r\n          <ModalBody>\r\n            <VStack spacing={4}>\r\n              <FormControl id=\"product\" isRequired>\r\n                <FormLabel>Product Name</FormLabel>\r\n                <Input\r\n                  name=\"product\"\r\n                  value={newCampaign.product}\r\n                  onChange={handleInputChange}\r\n                  bg={inputBgColor}\r\n                  borderColor={inputBorderColor}\r\n                />\r\n              </FormControl>\r\n\r\n              <FormControl id=\"description\" isRequired>\r\n                <FormLabel>Product Description</FormLabel>\r\n                <Textarea\r\n                  name=\"description\"\r\n                  value={newCampaign.description}\r\n                  onChange={handleInputChange}\r\n                  bg={inputBgColor}\r\n                  borderColor={inputBorderColor}\r\n                />\r\n              </FormControl>\r\n\r\n              <FormControl id=\"image\" isRequired>\r\n                <FormLabel>Product Image</FormLabel>\r\n                <Input\r\n                  type=\"file\"\r\n                  accept=\"image/*\"\r\n                  onChange={handleImageChange}\r\n                  p={1}\r\n                />\r\n                {selectedImage && (\r\n                  <Image\r\n                    src={selectedImage}\r\n                    alt=\"Selected product\"\r\n                    maxH=\"200px\"\r\n                    mt={2}\r\n                    borderRadius=\"md\"\r\n                  />\r\n                )}\r\n              </FormControl>\r\n\r\n              <FormControl id=\"originalPrice\" isRequired>\r\n                <FormLabel>Original Price (R)</FormLabel>\r\n                <NumberInput\r\n                  min={0}\r\n                  onChange={(valueString) => handleNumberInputChange('originalPrice', valueString)}\r\n                  value={newCampaign.originalPrice}\r\n                >\r\n                  <NumberInputField bg={inputBgColor} borderColor={inputBorderColor} />\r\n                  <NumberInputStepper>\r\n                    <NumberIncrementStepper />\r\n                    <NumberDecrementStepper />\r\n                  </NumberInputStepper>\r\n                </NumberInput>\r\n              </FormControl>\r\n\r\n              <FormControl id=\"groupPrice\" isRequired>\r\n                <FormLabel>Group Price (R)</FormLabel>\r\n                <NumberInput\r\n                  min={0}\r\n                  onChange={(valueString) => handleNumberInputChange('groupPrice', valueString)}\r\n                  value={newCampaign.groupPrice}\r\n                >\r\n                  <NumberInputField bg={inputBgColor} borderColor={inputBorderColor} />\r\n                  <NumberInputStepper>\r\n                    <NumberIncrementStepper />\r\n                    <NumberDecrementStepper />\r\n                  </NumberInputStepper>\r\n                </NumberInput>\r\n              </FormControl>\r\n\r\n              <FormControl id=\"targetBuyers\" isRequired>\r\n                <FormLabel>Target Number of Buyers</FormLabel>\r\n                <NumberInput\r\n                  min={1}\r\n                  onChange={(valueString) => handleNumberInputChange('targetBuyers', valueString)}\r\n                  value={newCampaign.targetBuyers}\r\n                >\r\n                  <NumberInputField bg={inputBgColor} borderColor={inputBorderColor} />\r\n                  <NumberInputStepper>\r\n                    <NumberIncrementStepper />\r\n                    <NumberDecrementStepper />\r\n                  </NumberInputStepper>\r\n                </NumberInput>\r\n              </FormControl>\r\n\r\n              <FormControl id=\"deadline\" isRequired>\r\n                <FormLabel>Campaign Deadline</FormLabel>\r\n                <Input\r\n                  name=\"deadline\"\r\n                  type=\"date\"\r\n                  value={newCampaign.deadline}\r\n                  onChange={handleInputChange}\r\n                  bg={inputBgColor}\r\n                  borderColor={inputBorderColor}\r\n                />\r\n              </FormControl>\r\n            </VStack>\r\n          </ModalBody>\r\n\r\n          <ModalFooter>\r\n            <Button variant=\"ghost\" mr={3} onClick={onClose}>\r\n              Cancel\r\n            </Button>\r\n            <Button colorScheme=\"blue\" onClick={handleCreateCampaign}>\r\n              Create Campaign\r\n            </Button>\r\n          </ModalFooter>\r\n        </ModalContent>\r\n      </Modal>\r\n    </Box>\r\n  );\r\n}\r\n\r\nexport default GroupBuying;\r\n","/* eslint-disable no-unused-vars */\r\nimport React, { useMemo, useState, useEffect } from 'react';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport {\r\n  Box,\r\n  Flex,\r\n  Heading,\r\n  Text,\r\n  SimpleGrid,\r\n  VStack,\r\n  Button,\r\n  useColorModeValue,\r\n  Alert,\r\n  AlertIcon,\r\n  useToast,\r\n  Spinner,\r\n  Tooltip,\r\n} from '@chakra-ui/react';\r\nimport { FaArrowLeft, FaCreditCard, FaBolt, FaSun, FaShieldAlt, FaCheckCircle } from 'react-icons/fa';\r\nimport { motion } from 'framer-motion';\r\nimport { useSubscription } from '../context/SubscriptionContext';\r\n\r\nfunction SubscriptionPage() {\r\n  const navigate = useNavigate();\r\n  const toast = useToast();\r\n  const { selectPlan } = useSubscription();\r\n  \r\n  // Ensure all useColorModeValue calls are at the top level\r\n  const headingColor = useColorModeValue('gray.900', 'white');\r\n  const newCardBg = useColorModeValue('rgba(255, 255, 255, 0.85)', 'rgba(17, 25, 40, 0.75)');\r\n  const newBorderColor = useColorModeValue('gray.300', 'gray.700');\r\n  \r\n  const subscriptionPlans = useMemo(() => [\r\n    {\r\n      id: 'basic-lite',\r\n      name: 'Basic Lite',\r\n      price: 29,\r\n      features: [\r\n        'Limited access to core features',\r\n        'Basic energy tracking',\r\n        'Standard email support'\r\n      ],\r\n      description: 'Ideal for newcomers, this plan offers a simple introduction to energy management with easy-to-use tools and community tips.'\r\n    },\r\n    {\r\n      id: 'basic',\r\n      name: 'Basic',\r\n      price: 49,\r\n      features: [\r\n        'Access to core features',\r\n        'Basic energy usage tracking',\r\n        'Email support'\r\n      ],\r\n      description: 'A solid starting point for everyday users, focusing on reliable tracking and essential tools for home energy optimization.'\r\n    },\r\n    {\r\n      id: 'basic-plus',\r\n      name: 'Basic Plus',\r\n      price: 69,\r\n      features: [\r\n        'All Basic features',\r\n        'Enhanced tracking reports',\r\n        'Priority email support'\r\n      ],\r\n      description: 'Step up with advanced reports and priority support, perfect for users looking to dive deeper into their energy habits.'\r\n    },\r\n    {\r\n      id: 'standard-lite',\r\n      name: 'Standard Lite',\r\n      price: 79,\r\n      features: [\r\n        'Most Standard features',\r\n        'Basic analytics',\r\n        'Email and chat support',\r\n        'Standard notifications'\r\n      ],\r\n      description: 'A balanced plan for moderate users, including analytics and notifications to help manage energy more efficiently.'\r\n    },\r\n    {\r\n      id: 'standard',\r\n      name: 'Standard',\r\n      price: 99,\r\n      features: [\r\n        'All Basic features',\r\n        'Detailed analytics & reports',\r\n        'Priority email & chat support',\r\n        'Load shedding notifications'\r\n      ],\r\n      description: 'Comprehensive analytics for proactive energy management, with real-time notifications to stay ahead of usage.'\r\n    },\r\n    {\r\n      id: 'standard-plus',\r\n      name: 'Standard Plus',\r\n      price: 119,\r\n      features: [\r\n        'All Standard features',\r\n        'Advanced reports',\r\n        '24/7 support',\r\n        'Enhanced notifications'\r\n      ],\r\n      description: 'Elevate your experience with 24/7 support and advanced tools, ideal for families or small businesses.'\r\n    },\r\n    {\r\n      id: 'premium',\r\n      name: 'Premium',\r\n      price: 149,\r\n      features: [\r\n        'All Standard features',\r\n        'Real-time energy monitoring',\r\n        'Dedicated account manager',\r\n        'Early access to new features',\r\n        'VIP support'\r\n      ],\r\n      description: ''\r\n    },\r\n    {\r\n      id: 'premium-plus',\r\n      name: 'Premium Plus',\r\n      price: 309,\r\n      features: [\r\n        'All Premium features',\r\n        'Enhanced real-time monitoring',\r\n        'Dedicated manager',\r\n        'VIP access and support'\r\n      ],\r\n      description: 'Unlock dedicated support and real-time insights, tailored for users who demand the best in energy solutions.'\r\n    },\r\n  ], []);\r\n\r\n  const [selectedPlans, setSelectedPlans] = useState([]);\r\n  const [rationale] = useState({});\r\n  \r\n  useEffect(() => {\r\n    const savedPlans = localStorage.getItem('selectedPlans');\r\n    if (savedPlans) {\r\n      setSelectedPlans(JSON.parse(savedPlans));\r\n    }\r\n  }, []);\r\n  \r\n  const mockRationaleMessages = [\r\n    \"This plan suits your low energy usage pattern based on mock data analysis.\",\r\n    \"Based on your data, this is a great match for high efficiency needs.\",\r\n    \"Ideal for users with moderate usage; it optimizes costs effectively.\",\r\n    \"This option aligns well with your peak-hour energy patterns.\",\r\n    \"Perfect for solar-dependent setups like yours.\",\r\n    \"Enhances your energy tracking with minimal investment.\",\r\n    \"A smart choice for reducing your carbon footprint.\",\r\n    \"Tailored for users seeking reliable load shedding solutions.\",\r\n    \"Boosts your energy management with advanced features.\",\r\n    \"Great for everyday efficiency and cost savings.\",\r\n    \"This plan fits users with variable energy demands.\",\r\n    \"Optimizes for low-usage scenarios to save more.\",\r\n    \"Balances cost and features for your energy profile.\",\r\n    \"Supports real-time monitoring for better decisions.\",\r\n    \"Ideal if you're focusing on sustainable energy sources.\",\r\n    \"Provides excellent value for high-usage households.\",\r\n    \"Enhances notifications for proactive energy management.\",\r\n    \"A solid pick for users prioritizing 24/7 support.\",\r\n    \"Matches your needs for detailed analytics reports.\",\r\n    \"Streamlines your energy optimization efforts.\",\r\n    \"Best for those with growing energy requirements.\",\r\n    \"Delivers premium insights at an affordable rate.\",\r\n    \"Adapts to your energy habits for maximum efficiency.\",\r\n    \"Unlocks advanced tools for energy conservation.\",\r\n    \"Suited for users with solar and grid hybrid systems.\",\r\n    \"Offers robust features for budget-conscious users.\",\r\n    \"Elevates your setup with priority support options.\",\r\n    \"Tailored for peak performance in energy tracking.\",\r\n    \"A versatile plan for mixed energy usage patterns.\",\r\n    \"Focuses on cost-effective solutions for you.\",\r\n    \"Integrates well with your current energy setup.\",\r\n    \"Provides comprehensive monitoring for better savings.\",\r\n    \"Ideal for users expanding their energy systems.\",\r\n    \"Enhances your experience with real-time data insights.\",\r\n    \"Perfect match for low-maintenance energy needs.\",\r\n    \"Boosts efficiency for users with high demands.\",\r\n    \"Supports your goals for sustainable living.\",\r\n    \"A reliable choice for everyday energy challenges.\",\r\n    \"Optimizes for users with fluctuating usage.\",\r\n    \"Delivers value through advanced reporting features.\",\r\n    \"Great for those seeking customizable energy plans.\",\r\n    \"Aligns with your profile for optimal energy use.\",\r\n    \"Enhances control over your energy consumption.\",\r\n    \"Tailored to handle your specific energy patterns.\",\r\n    \"Provides a strong foundation for energy management.\",\r\n    \"Ideal for proactive users monitoring their usage.\",\r\n    \"Balances features and cost for your needs.\",\r\n    \"Unlocks potential savings with smart analytics.\",\r\n    \"Suited for dynamic energy environments.\",\r\n    \"Offers premium support for peace of mind.\",\r\n    \"A top pick for efficient and eco-friendly options.\"\r\n  ];\r\n\r\n  const handleSelectPlan = (plan) => {\r\n    selectPlan(plan);\r\n    window.location.href = '/dashboard';\r\n  };\r\n\r\n  const fetchPlanRationale = async (planId) => {\r\n    // Implementation of fetchPlanRationale function\r\n  };\r\n\r\n  return (\r\n    <Flex\r\n      minH=\"100vh\"\r\n      align=\"center\"\r\n      justify=\"center\"\r\n      p={4}\r\n      backgroundImage=\"linear-gradient(to bottom right, #FF8C42, #4A00E0)\"\r\n      backgroundSize=\"cover\"\r\n      backgroundPosition=\"center\"\r\n      backgroundAttachment=\"fixed\"\r\n      position=\"relative\"\r\n      _before={{\r\n        content: '\"\"',\r\n        position: 'absolute',\r\n        top: 0,\r\n        left: 0,\r\n        right: 0,\r\n        bottom: 0,\r\n        bg: 'rgba(0, 0, 0, 0.5)',\r\n        zIndex: 1,\r\n      }}\r\n    >\r\n      <Box\r\n        maxW=\"container.xl\"\r\n        py={8}\r\n        position=\"relative\"\r\n        zIndex={2}\r\n      >\r\n        <Flex justify=\"space-between\" align=\"center\" mb={8}>\r\n          <Button\r\n            leftIcon={<FaArrowLeft />}\r\n            onClick={() => navigate(-1)}\r\n            variant=\"ghost\"\r\n          >\r\n            Back\r\n          </Button>\r\n          <Heading as=\"h1\" size=\"xl\" color={headingColor}>\r\n            <FaCreditCard style={{ display: 'inline-block', marginRight: '0.5rem' }} />\r\n            Subscription Plans\r\n          </Heading>\r\n          <Box w=\"136px\" />\r\n        </Flex>\r\n        <Alert status=\"info\" mb={8} borderRadius=\"md\">\r\n          <AlertIcon />\r\n          Choose the plan that best fits your energy management needs\r\n        </Alert>\r\n        <SimpleGrid columns={{ base: 1, sm: 2, md: 3, lg: 4 }} spacing={8}>\r\n          {subscriptionPlans.map((plan) => (\r\n            <motion.div key={plan.id} initial={{ opacity: 0, y: 50 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: 0.5 }} whileHover={{ scale: 1.05, boxShadow: '0px 10px 20px rgba(0, 0, 0, 0.1)' }} style={{ height: '100%' }}>\r\n              <Box p={6} borderWidth=\"1px\" borderRadius=\"md\" bg={newCardBg} boxShadow=\"lg\" _hover={{ boxShadow: 'xl' }} display=\"flex\" flexDirection=\"column\" alignItems=\"center\" justifyContent=\"flex-start\" height=\"100%\" minH=\"340px\" maxW=\"320px\" mx=\"auto\" backdropFilter=\"blur(10px)\" borderColor={selectedPlans.includes(plan.id) ? 'green.500' : newBorderColor}>\r\n                <VStack spacing={4} align=\"stretch\" height=\"100%\">\r\n                  <Flex align=\"center\" justify=\"center\">\r\n                    {plan.id.includes('basic') && <FaBolt size=\"24px\" color=\"blue\" />}\r\n                    {plan.id.includes('standard') && <FaSun size=\"24px\" color=\"yellow\" />}\r\n                    {plan.id.includes('premium') && <FaShieldAlt size=\"24px\" color=\"gold\" />}\r\n                    <Heading size=\"md\" color={headingColor} ml={2}>{plan.name}</Heading>\r\n                  </Flex>\r\n                  <Text fontSize=\"2xl\" fontWeight=\"bold\" color=\"green.500\">R{plan.price}/month</Text>\r\n                  <VStack align=\"start\" spacing={2} flex=\"1\" maxH=\"120px\" overflowY=\"auto\">\r\n                    {plan.features.map((feature, index) => (\r\n                      <Flex key={index} align=\"center\">\r\n                        <FaCheckCircle color=\"green\" />\r\n                        <Text ml={2}>{feature}</Text>\r\n                      </Flex>\r\n                    ))}\r\n                  </VStack>\r\n                  <Button onClick={() => handleSelectPlan(plan)} colorScheme={selectedPlans.includes(plan.id) ? 'red' : 'green'} width=\"full\">{selectedPlans.includes(plan.id) ? 'Unselect' : 'Select'}</Button>\r\n                  <Button onClick={() => fetchPlanRationale(plan.id)}>Get Rationale</Button>\r\n                </VStack>\r\n                {selectedPlans.includes(plan.id) && (\r\n                  <Box mt={4}>\r\n                    {rationale[plan.id]?.isLoading ? (\r\n                      <Spinner size=\"md\" />\r\n                    ) : rationale[plan.id]?.message ? (\r\n                      <Tooltip label={rationale[plan.id].message} hasArrow placement=\"top\">\r\n                        <Text color=\"gray.600\" fontSize=\"sm\">\r\n                          {rationale[plan.id].message.slice(0, 50)}...\r\n                        </Text>\r\n                      </Tooltip>\r\n                    ) : null}\r\n                  </Box>\r\n                )}\r\n              </Box>\r\n            </motion.div>\r\n          ))}\r\n        </SimpleGrid>\r\n      </Box>\r\n    </Flex>\r\n  );\r\n}\r\n\r\nexport default SubscriptionPage; ","import React, { useState } from 'react';\r\nimport { Box, Heading, Text, Button, useToast, SimpleGrid } from '@chakra-ui/react';\r\nimport { motion } from 'framer-motion';  // Import for animations\r\n\r\nconst AISuggestions = () => {\r\n  const allSuggestions = Array.from({ length: 1000 }, (_, index) => `Save energy by optimizing device usage, such as turning off unused appliances. Suggestion variation: Try ${index + 1}.`);  // Generate 1000 mock suggestions without numbering\r\n\r\n  function getRandomSuggestions() {\r\n    const shuffled = allSuggestions.sort(() => 0.5 - Math.random());\r\n    return shuffled.slice(0, 3);\r\n  }\r\n\r\n  const toast = useToast();\r\n  const [displayedSuggestions, setDisplayedSuggestions] = useState(getRandomSuggestions());\r\n\r\n  const handleRefresh = () => {\r\n    setDisplayedSuggestions(getRandomSuggestions());\r\n    toast({\r\n      title: 'Suggestions refreshed.',\r\n      status: 'success',\r\n      duration: 2000,\r\n      isClosable: true,\r\n    });\r\n  };\r\n\r\n  return (\r\n    <Box p={5} bg=\"white\" borderRadius=\"md\" boxShadow=\"md\">  {/* Match home page style with background, shadow, and rounding */}\r\n      <Heading as=\"h1\" size=\"xl\" mb={4}>AI Suggestions</Heading>\r\n      <Text mb={4}>Here are smart tips from our AI engine to help you save energy and manage your finances better.</Text>\r\n      <Button mt={4} onClick={handleRefresh}>Refresh Suggestions</Button>\r\n      <SimpleGrid columns={1} spacing={4} mt={4}>\r\n        {displayedSuggestions.map((suggestion, index) => (\r\n          <motion.Box\r\n            key={index}\r\n            initial={{ opacity: 0, y: 20 }}\r\n            animate={{ opacity: 1, y: 0 }}\r\n            transition={{ duration: 0.5 }}\r\n            p={4}\r\n            borderWidth=\"1px\"\r\n            borderRadius=\"md\"\r\n            boxShadow=\"sm\"\r\n            bg=\"gray.50\"\r\n          >\r\n            <Text>{suggestion}</Text>\r\n          </motion.Box>\r\n        ))}\r\n      </SimpleGrid>\r\n    </Box>\r\n  );\r\n};\r\n\r\nexport default AISuggestions;","import React, { useState, useEffect } from \"react\";\nimport {\n  Box,\n  Heading,\n  FormControl,\n  FormLabel,\n  Input,\n  Button,\n  VStack,\n  useToast,\n  AlertDialog,\n  AlertDialogBody,\n  AlertDialogFooter,\n  AlertDialogHeader,\n  AlertDialogContent,\n  AlertDialogOverlay,\n} from \"@chakra-ui/react\";\nimport axios from \"axios\";\n\nconst PersonalUserPage = () => {\n  const toast = useToast();\n  const cancelRef = React.useRef();\n\n  const [formData, setFormData] = useState({\n    full_name: \"\",\n    surname: \"\",\n    email: \"\",\n    phone_number: \"\",\n    address: \"\",\n  });\n\n  const [isOpen, setIsOpen] = useState(false);\n\n  useEffect(() => {\n    axios\n      .get(\"/api/auth/user\", { withCredentials: true })\n      .then((res) => setFormData(res.data))\n      .catch(() =>\n        toast({\n          title: \"Failed to load user data\",\n          status: \"error\",\n          isClosable: true,\n        })\n      );\n  }, [toast]);\n\n  const handleChange = (e) => {\n    setFormData((prev) => ({ ...prev, [e.target.name]: e.target.value }));\n  };\n\n  const handleSubmit = (e) => {\n    e.preventDefault();\n    setIsOpen(true);\n  };\n\n  const confirmSubmit = () => {\n    setIsOpen(false);\n    axios\n      .put(\"/api/auth/user\", formData, { withCredentials: true })\n      .then(() =>\n        toast({\n          title: \"Profile updated successfully\",\n          status: \"success\",\n          isClosable: true,\n        })\n      )\n      .catch((error) => {\n        console.error('Update error:', error.response ? error.response.data : error.message);\n        toast({\n          title: \"Update failed\",\n          description: error.response ? error.response.data.message : 'An unknown error occurred',\n          status: \"error\",\n          isClosable: true,\n        });\n      });\n  };\n\n  return (\n    <Box p={6} maxW=\"600px\" mx=\"auto\">\n      <Heading mb={6}>Personal User Information</Heading>\n      <form onSubmit={handleSubmit}>\n        <VStack spacing={4}>\n          <FormControl isRequired>\n            <FormLabel>Full Name</FormLabel>\n            <Input name=\"full_name\" value={formData.full_name} onChange={handleChange} />\n          </FormControl>\n\n          <FormControl isRequired>\n            <FormLabel>Surname</FormLabel>\n            <Input name=\"surname\" value={formData.surname} onChange={handleChange} />\n          </FormControl>\n\n          <FormControl>\n            <FormLabel>Email</FormLabel>\n            <Input type=\"email\" name=\"email\" value={formData.email} onChange={handleChange} />\n          </FormControl>\n\n          <FormControl>\n            <FormLabel>Phone Number</FormLabel>\n            <Input name=\"phone_number\" value={formData.phone_number} onChange={handleChange} />\n          </FormControl>\n\n          <FormControl>\n            <FormLabel>Address</FormLabel>\n            <Input name=\"address\" value={formData.address} onChange={handleChange} />\n          </FormControl>\n\n          <Button colorScheme=\"blue\" type=\"submit\" width=\"full\">\n            Save Changes\n          </Button>\n        </VStack>\n      </form>\n\n      <AlertDialog isOpen={isOpen} leastDestructiveRef={cancelRef} onClose={() => setIsOpen(false)}>\n        <AlertDialogOverlay>\n          <AlertDialogContent>\n            <AlertDialogHeader fontSize=\"lg\" fontWeight=\"bold\">\n              Confirm Changes\n            </AlertDialogHeader>\n\n            <AlertDialogBody>\n              Are you sure you want to save these changes to your profile?\n            </AlertDialogBody>\n\n            <AlertDialogFooter>\n              <Button ref={cancelRef} onClick={() => setIsOpen(false)}>\n                Cancel\n              </Button>\n              <Button colorScheme=\"blue\" onClick={confirmSubmit} ml={3}>\n                Save\n              </Button>\n            </AlertDialogFooter>\n          </AlertDialogContent>\n        </AlertDialogOverlay>\n      </AlertDialog>\n    </Box>\n  );\n};\n\nexport default PersonalUserPage; ","import React, { useEffect } from 'react';\r\nimport { Box, Heading, Text, VStack, UnorderedList, ListItem, Container, useColorModeValue, IconButton } from '@chakra-ui/react';\r\nimport backgroundImage from '../assets/images/Terms_Page_And_Services.png';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { FaArrowLeft } from 'react-icons/fa';\r\n\r\nconsole.log('Imported background image:', backgroundImage);  // Debug log for image\r\n\r\nfunction PrivacyPolicyPage() {\r\n  const navigate = useNavigate();\r\n  const overlayBg = useColorModeValue('rgba(255, 255, 255, 0.1)', 'rgba(0, 0, 0, 0.15)');\r\n  const textColor = useColorModeValue('gray.700', 'gray.100');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const listColor = useColorModeValue('gray.600', 'gray.300');\r\n\r\n  useEffect(() => {\r\n    console.log('PrivacyPolicyPage is rendering with styles check');\r\n  }, []);\r\n\r\n  return (\r\n    <Box position=\"relative\" minH=\"100vh\" py={10}>\r\n      <IconButton\r\n        aria-label=\"Back\"\r\n        icon={<FaArrowLeft />}\r\n        size=\"sm\"\r\n        position=\"absolute\"\r\n        top=\"1rem\"\r\n        left=\"1rem\"\r\n        onClick={() => navigate(-1)}\r\n        zIndex=\"3\"\r\n      />\r\n      <Box\r\n        position=\"absolute\"\r\n        top={0}\r\n        left={0}\r\n        w=\"100%\"\r\n        h=\"100%\"\r\n        backgroundImage={`url(${backgroundImage})`}\r\n        backgroundSize=\"cover\"\r\n        backgroundPosition=\"center\"\r\n        _before={{\r\n          content: '\"\"',\r\n          position: 'absolute',\r\n          top: 0,\r\n          left: 0,\r\n          right: 0,\r\n          bottom: 0,\r\n          bg: overlayBg,\r\n          backdropFilter: 'blur(2px)'\r\n        }}\r\n      />\r\n      <Container \r\n        maxW=\"3xl\" \r\n        position=\"relative\"\r\n        zIndex=\"2\"\r\n        bg={useColorModeValue('rgba(255, 255, 255, 0.85)', 'rgba(17, 25, 40, 0.85)')}\r\n        backdropFilter=\"blur(10px)\"\r\n        borderRadius=\"lg\"\r\n        boxShadow=\"md\"\r\n        p={8}\r\n        sx={{\r\n          WebkitBackdropFilter: 'blur(10px)',\r\n        }}\r\n      >\r\n        <Heading as=\"h2\" size=\"xl\" mb={6} textAlign=\"center\" color={headingColor}>\r\n          Privacy Policy for Gridx\r\n        </Heading>\r\n        <Text color={textColor} mb={4}>Effective Date: [Insert Date]</Text>\r\n        <VStack align=\"start\" spacing={6} color={textColor}>\r\n          <Text>\r\n            Welcome to Gridx! Your privacy is important to us, and this policy explains how we collect, use, and protect your information when you use our web application.\r\n          </Text>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>1. What Information We Collect</Heading>\r\n            <Text>\r\n              <b>Personal Information:</b> Name, email address, phone number, and other registration details.<br />\r\n              <b>Usage Data:</b> Solar energy usage statistics, financial/expense tracking inputs, and feature interactions.<br />\r\n              <b>Device & Technical Info:</b> IP address, browser type, device type, and cookies.<br />\r\n              <b>Community Data (if applicable):</b> Profile photo, shared posts, and messages within community features.\r\n            </Text>\r\n          </Box>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>2. Why We Collect Your Data</Heading>\r\n            <Text>We collect data to:</Text>\r\n            <UnorderedList spacing={3} pl={5} color={listColor}>\r\n              <ListItem>Provide and improve your experience on Gridx.</ListItem>\r\n              <ListItem>Track solar usage and financial data to generate insights.</ListItem>\r\n              <ListItem>Customize content and recommendations.</ListItem>\r\n              <ListItem>Communicate with you (emails, alerts, reminders).</ListItem>\r\n              <ListItem>Ensure security and detect misuse.</ListItem>\r\n            </UnorderedList>\r\n          </Box>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>3. How We Store and Protect Your Data</Heading>\r\n            <Text>\r\n              We use secure servers and encryption to protect your personal data.<br />\r\n              Your information is stored on secure databases and cloud infrastructure.<br />\r\n              Access is restricted to authorized personnel only.<br />\r\n              We regularly update our systems for security.\r\n            </Text>\r\n          </Box>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>4. Cookies and Analytics</Heading>\r\n            <Text>\r\n              We use cookies to personalize your experience and remember your preferences.<br />\r\n              We may use third-party analytics (e.g., Google Analytics) to understand usage trends.<br />\r\n              You can disable cookies in your browser, but some features may not work properly.\r\n            </Text>\r\n          </Box>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>5. Sharing Your Information</Heading>\r\n            <Text>We do not sell or share your personal data with third parties, except:</Text>\r\n            <UnorderedList spacing={3} pl={5} color={listColor}>\r\n              <ListItem>With your consent.</ListItem>\r\n              <ListItem>With trusted vendors (e.g., email providers) who help us operate Gridx.</ListItem>\r\n              <ListItem>When required by law or to protect rights/safety.</ListItem>\r\n            </UnorderedList>\r\n          </Box>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>6. Your Rights and Choices</Heading>\r\n            <Text>You have the right to:</Text>\r\n            <UnorderedList spacing={3} pl={5} color={listColor}>\r\n              <ListItem>Access your personal data.</ListItem>\r\n              <ListItem>Correct or update your information.</ListItem>\r\n              <ListItem>Request deletion of your account and associated data.</ListItem>\r\n              <ListItem>Opt-out of marketing communications at any time.</ListItem>\r\n            </UnorderedList>\r\n            <Text>To do any of the above, contact us at [Insert Contact Email].</Text>\r\n          </Box>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>7. Children's Privacy</Heading>\r\n            <Text>\r\n              Gridx is not intended for children under 13. We do not knowingly collect personal information from children.\r\n            </Text>\r\n          </Box>\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>8. Contact Us</Heading>\r\n            <Text>\r\n              If you have any questions or concerns about your privacy, please reach out to:<br />\r\n              📧 Email: [Insert Privacy Contact Email]<br />\r\n              📍 Address (optional): [Insert Company Address]\r\n            </Text>\r\n          </Box>\r\n        </VStack>\r\n      </Container>\r\n    </Box>\r\n  );\r\n}\r\n\r\nexport default PrivacyPolicyPage;\r\n","import React, { useEffect } from 'react';\r\nimport { Box, Heading, Text, VStack, Container, useColorModeValue, IconButton } from '@chakra-ui/react';\r\nimport backgroundImage from '../assets/images/Terms_Page_And_Services.png';\r\nimport { useNavigate } from 'react-router-dom';\r\nimport { FaArrowLeft } from 'react-icons/fa';\r\n\r\nfunction TermsOfServicePage() {\r\n  const navigate = useNavigate();\r\n  const overlayBg = useColorModeValue('rgba(255, 255, 255, 0.1)', 'rgba(0, 0, 0, 0.15)');\r\n  const glassBg = useColorModeValue('rgba(255, 255, 255, 0.85)', 'rgba(17, 25, 40, 0.85)');\r\n  const borderColor = useColorModeValue('rgba(255, 255, 255, 0.3)', 'rgba(255, 255, 255, 0.1)');\r\n  const textColor = useColorModeValue('gray.700', 'gray.100');\r\n  const headingColor = useColorModeValue('gray.800', 'white');\r\n  const listColor = useColorModeValue('gray.600', 'gray.300');\r\n\r\n  useEffect(() => {\r\n    console.log('TermsOfServicePage is rendering with styles check');\r\n    console.log('Background image URL being used:', `url(${backgroundImage})`);\r\n  }, []);\r\n\r\n  return (\r\n    <Box minH=\"100vh\" position=\"relative\" py={10}>\r\n      <IconButton\r\n        aria-label=\"Back\"\r\n        icon={<FaArrowLeft />}\r\n        size=\"sm\"\r\n        position=\"absolute\"\r\n        top=\"1rem\"\r\n        left=\"1rem\"\r\n        onClick={() => navigate(-1)}\r\n        zIndex=\"3\"\r\n      />\r\n      {/* Background image with overlay */}\r\n      <Box\r\n        position=\"absolute\"\r\n        top={0}\r\n        left={0}\r\n        w=\"100%\"\r\n        h=\"100%\"\r\n        backgroundImage={`url(${backgroundImage})`}\r\n        backgroundPosition=\"center\"\r\n        backgroundSize=\"cover\"\r\n        backgroundRepeat=\"no-repeat\"\r\n        _before={{\r\n          content: '\"\"',\r\n          position: 'absolute',\r\n          top: 0,\r\n          left: 0,\r\n          right: 0,\r\n          bottom: 0,\r\n          bg: overlayBg,\r\n          backdropFilter: 'blur(2px)',\r\n        }}\r\n      />\r\n      \r\n      <Container \r\n        maxW=\"3xl\" \r\n        position=\"relative\"\r\n        zIndex=\"2\"\r\n        bg={glassBg}\r\n        backdropFilter=\"blur(12px) saturate(160%)\"\r\n        borderRadius=\"xl\"\r\n        border=\"1px solid\"\r\n        borderColor={borderColor}\r\n        boxShadow=\"0 8px 32px rgba(0, 0, 0, 0.18)\"\r\n        p={8}\r\n        sx={{\r\n          WebkitBackdropFilter: 'blur(12px) saturate(160%)',\r\n        }}\r\n      >\r\n        <Heading as=\"h2\" size=\"xl\" mb={6} textAlign=\"center\" color={headingColor}>\r\n          Terms of Service for Gridx\r\n        </Heading>\r\n        <Text color={textColor} mb={4}>Effective Date: [Insert Date]</Text>\r\n        <VStack align=\"start\" spacing={6} color={textColor}>\r\n          <Text>\r\n            Welcome to Gridx! These Terms of Service (“Terms”) govern your use of our web app. By accessing or using Gridx, you agree to these Terms.\r\n          </Text>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>1. Your Gridx Account</Heading>\r\n            <Text>\r\n              You must be at least 13 years old to create an account.<br />\r\n              You are responsible for keeping your login credentials secure.<br />\r\n              You agree to provide accurate and complete information during registration.\r\n            </Text>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>2. User Responsibilities</Heading>\r\n            <Text mb={2}>You agree not to:</Text>\r\n            <Box as=\"ul\" pl={6} color={listColor}>\r\n              <li>Use Gridx for unlawful, harmful, or abusive activities.</li>\r\n              <li>Upload or share offensive, misleading, or malicious content.</li>\r\n              <li>Attempt to hack, exploit, or disrupt Gridx or its users.</li>\r\n              <li>Violate any applicable laws or regulations.</li>\r\n            </Box>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>3. Data and Content</Heading>\r\n            <Text>\r\n              You retain ownership of the data you submit (e.g., usage, expenses).<br />\r\n              By using community features, you give us permission to display your shared content within the platform.<br />\r\n              We may anonymize data to improve services and insights.\r\n            </Text>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>4. Service Availability</Heading>\r\n            <Text>\r\n              We aim to provide uninterrupted service but cannot guarantee 100% uptime.<br />\r\n              We may modify, update, or suspend parts of the app at any time with notice where possible.\r\n            </Text>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>5. Termination</Heading>\r\n            <Text>\r\n              You can delete your account at any time.<br />\r\n              We may suspend or terminate your access if you violate these Terms or engage in harmful behavior.\r\n            </Text>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>6. Intellectual Property</Heading>\r\n            <Text>\r\n              Gridx and all related designs, logos, and code are the property of [Your Company Name].<br />\r\n              You may not copy, reproduce, or reverse-engineer any part of Gridx without permission.\r\n            </Text>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>7. Limitation of Liability</Heading>\r\n            <Text mb={2}>We are not liable for:</Text>\r\n            <Box as=\"ul\" pl={6} color={listColor}>\r\n              <li>Any damages resulting from your use or inability to use the platform.</li>\r\n              <li>Loss of data, profits, or reputation.</li>\r\n              <li>Third-party content or links accessed through Gridx.</li>\r\n            </Box>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>8. Changes to These Terms</Heading>\r\n            <Text>\r\n              We may update these Terms from time to time. If we do, we'll notify you via the app or email. Continued use means you agree to the new terms.\r\n            </Text>\r\n          </Box>\r\n\r\n          <Box>\r\n            <Heading as=\"h3\" size=\"md\" mb={2} color={headingColor}>9. Contact Information</Heading>\r\n            <Text>\r\n              If you have any questions or need assistance, please contact us at [Your Company Email] or [Your Company Phone Number].\r\n            </Text>\r\n          </Box>\r\n        </VStack>\r\n      </Container>\r\n    </Box>\r\n  );\r\n}\r\n\r\nexport default TermsOfServicePage;","import React from 'react';\r\nimport { \r\n  Routes, \r\n  Route, \r\n  Navigate, \r\n  Outlet \r\n} from 'react-router-dom';\r\nimport { BrowserRouter as Router } from 'react-router-dom';\r\nimport { auth } from './services/api'; // Assuming auth service is still needed\r\nimport Supportbot from './components/Supportbot'; // Correct casing\r\nimport LoadSheddingPage from './pages/LoadSheddingPage';\r\nimport ErrorBoundary from './components/ErrorBoundary';\r\nimport { ChakraProvider } from '@chakra-ui/react';\r\nimport theme from './theme';\r\nimport { DashboardProvider } from './context/DashboardContext';\r\nimport { SubscriptionProvider } from './context/SubscriptionContext';\r\n\r\nimport LandingPage from './pages/LandingPage';\r\nimport RegisterPage from './pages/RegisterPage';\r\nimport LoginPage from './pages/LoginPage';\r\nimport AboutPage from './pages/AboutPage';\r\nimport OAuthCallbackHandler from './pages/OAuthCallbackHandler';\r\nimport HomePage from './pages/HomePage';\r\nimport DashboardPage from './pages/DashboardPage';\r\nimport TopUpPage from './pages/TopUpPage';\r\nimport SettingsPage from './pages/SettingsPage';\r\nimport ImpactPage from './pages/ImpactPage';\r\nimport ExpensesPage from './pages/ExpensesPage';\r\nimport NotificationsPage from './pages/NotificationsPage';\r\nimport SupportPage from './pages/SupportPage';\r\nimport ForumPage from './pages/ForumPage';\r\nimport ReferPage from './pages/ReferPage';\r\nimport GroupBuying from './pages/GroupBuying';\r\nimport SubscriptionPage from './pages/SubscriptionPage';\r\nimport AISuggestions from './pages/AISuggestions';\r\nimport PersonalUserPage from './pages/PersonalUserPage';\r\nimport PrivacyPolicyPage from './pages/PrivacyPolicyPage';\r\nimport TermsOfServicePage from './pages/TermsOfServicePage';\r\n\r\n// Protected Route component\r\nconst ProtectedRoute = () => {\r\n  const user = auth.getCurrentUser(); // Check if user data/token exists\r\n  console.log('ProtectedRoute: User is', user ? 'authenticated' : 'not authenticated');  // Added for debugging\r\n  if (!user) {\r\n    // If no user (no token), redirect to login\r\n    return <Navigate to=\"/login\" replace />;\r\n  }\r\n  // If user exists, render the nested routes\r\n  return <Outlet />;\r\n};\r\n\r\nfunction App() {\r\n  return (\r\n    <ErrorBoundary>\r\n      <ChakraProvider theme={theme}>\r\n        <DashboardProvider>\r\n          <SubscriptionProvider>\r\n            <Router>\r\n              <Routes>\r\n                {/* Public Routes */}\r\n                <Route path=\"/\" element={<LandingPage />} />\r\n                <Route path=\"/register\" element={<RegisterPage />} />\r\n                <Route path=\"/login\" element={<LoginPage />} />\r\n                <Route path=\"/about\" element={<AboutPage />} /> {/* About Page route */}\r\n\r\n                {/* Add OAuth callback route */}\r\n                <Route path=\"/auth/callback\" element={<OAuthCallbackHandler />} />\r\n\r\n                {/* Protected Routes */}\r\n                <Route element={<ProtectedRoute />}>\r\n                  <Route path=\"/home\" element={<HomePage />} />\r\n                  <Route path=\"/dashboard\" element={<DashboardPage />} />\r\n                  <Route path=\"/top-up\" element={<TopUpPage />} />\r\n                  <Route path=\"/settings\" element={<SettingsPage />} />\r\n                  <Route path=\"/impact\" element={<ImpactPage />} />\r\n                  <Route path=\"/expenses\" element={<ExpensesPage />} />\r\n                  <Route path=\"/notifications\" element={<NotificationsPage />} />\r\n                  <Route path=\"/support\" element={<SupportPage />} />\r\n                  <Route path=\"/forum\" element={<ForumPage />} />\r\n                  <Route path=\"/loadshedding\" element={<LoadSheddingPage />} />\r\n                  <Route path=\"/refer\" element={<ReferPage />} />\r\n                  <Route path=\"/group-buying\" element={<GroupBuying />} />\r\n                  <Route path=\"/subscription\" element={<SubscriptionPage />} />\r\n                  <Route path=\"/ai-suggestions\" element={<AISuggestions />} />\r\n                  <Route path=\"/personal-user\" element={<PersonalUserPage />} />\r\n                </Route>\r\n\r\n                {/* New Routes */}\r\n                <Route path=\"/privacy-policy\" element={<PrivacyPolicyPage />} />\r\n                <Route path=\"/terms-of-service\" element={<TermsOfServicePage />} />\r\n\r\n                {/* Fallback route */}\r\n                <Route path=\"*\" element={<Navigate to=\"/\" replace />} />\r\n              </Routes>\r\n              <Supportbot />\r\n            </Router>\r\n          </SubscriptionProvider>\r\n        </DashboardProvider>\r\n      </ChakraProvider>\r\n    </ErrorBoundary>\r\n  );\r\n}\r\n\r\nexport default App;\r\n","import React from 'react';\r\nimport ReactDOM from 'react-dom/client';\r\nimport './index.css';\r\nimport App from './App';\r\nimport { ChakraProvider, extendTheme, ColorModeScript } from '@chakra-ui/react';\r\n\r\n// Extend the default theme to configure color mode\r\nconst config = {\r\n  initialColorMode: 'light', // Set the initial color mode to 'light'\r\n  useSystemColorMode: false, // Disable using the system's color mode preference\r\n};\r\n\r\nconst theme = extendTheme({ config });\r\n\r\nconst root = ReactDOM.createRoot(document.getElementById('root'));\r\nroot.render(\r\n  <React.StrictMode>\r\n    <ColorModeScript initialColorMode={theme.config.initialColorMode} />\r\n    <ChakraProvider theme={theme}>\r\n      <App />\r\n    </ChakraProvider>\r\n  </React.StrictMode>\r\n);\r\n"],"names":["module","exports","val